from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass
from typing import cast

import src.key_catalog
from cloud.services.agent_runner_support.judge.types import ProfileExtractionResult
from src.agui import BaseEvent, PlannerStatusUpdate, PlannerToAGUIAdapter
from src.error_handling import build_error_outcome
from src.key_catalog import (
    OP_CHOOSE_OPTION,
    OP_SELECT_COMBOBOX,
    OP_SELECT_OPTION,
    OP_SET_BOOLEAN,
    OP_SET_TEXT,
    OP_UPLOAD_ATTACHMENT,
    PK_ATTACHMENT_SLOT,
    PK_CONTROL_ID,
    PK_CURRENT_VALUE,
    PK_EXPECTED_OPTION,
    PK_FIELD,
    PK_OPERATION,
    PK_PROFILE_DATA,
    PK_TEXT,
    PK_VALUE,
    SK_STATUS_UPDATES,
)
from src.logging import get_logger
from src.types.payload import resolve_profile_data
from src.types.typed import JsonObject, as_json_object, as_json_value
from src.types.types import JsonValue

logger = get_logger(__name__)


def coerce_json_object_list(value: object) -> list[JsonObject]:
    if not isinstance(value, list):
        return []
    items: list[JsonObject] = []
    raw_items = cast(list[object], value)
    for item in raw_items:
        if isinstance(item, dict):
            items.append(cast(JsonObject, item))
    return items


def document_asset_selection(result: dict[str, object]) -> JsonObject | None:
    """Extract top-level or latest valid tailoring status selection metadata."""
    selection = as_json_object(result.get("document_asset_selection")) or None

    if selection is None:
        for status_update in reversed(
            coerce_json_object_list(result.get(SK_STATUS_UPDATES))
        ):
            details = as_json_object(status_update.get("details"))
            selection = as_json_object(details.get("document_asset_selection")) or None
            if selection is not None:
                break
    return selection


def as_optional_string(value: object) -> str | None:
    if isinstance(value, str):
        return value
    return None


def as_optional_float(value: object) -> float | None:
    if isinstance(value, bool):
        return None
    if isinstance(value, int | float):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value)
        except ValueError as exc:
            logger.warning(
                "Unable to parse optional float payload value",
                value_preview=value[:80],
                value_length=len(value),
                exception_type=type(exc).__name__,
                exc_info=exc,
            )
            return None
    return None


@dataclass(frozen=True)
class ParseErrorContext:
    """Grouped context for parse-error diagnostics."""

    source: str
    field_name: str
    context: JsonObject
    message: str


def as_optional_float_result(
    value: object,
    error_ctx: ParseErrorContext,
) -> tuple[float | None, JsonObject | None]:
    parsed = as_optional_float(value)
    if parsed is not None or value is None:
        return parsed, None
    enriched_context = dict(error_ctx.context)
    enriched_context[PK_FIELD] = error_ctx.field_name
    enriched_context["value_type"] = type(value).__name__
    if isinstance(value, str) and value.strip():
        enriched_context["value_preview"] = value[:80]
    return (
        None,
        build_error_outcome(
            ValueError(error_ctx.message),
            context=enriched_context,
            severity=src.key_catalog.SV_WARNING,
            recoverable=True,
            source=error_ctx.source,
            message=error_ctx.message,
        ).to_payload(),
    )


def action_control_id(action: JsonObject) -> str:
    return as_optional_string(action.get(PK_CONTROL_ID)) or ""


def build_planner_summary(action: JsonObject) -> str:
    """Deprecated: returns empty so real LLM reasoning isn't masked by templates.

    Callers must source planner reasoning from PlannerAction.reasoning or judge_reason.
    """
    del action
    return ""


def field_control_id(field_payload: JsonObject) -> str:
    return as_optional_string(field_payload.get(PK_CONTROL_ID)) or ""


@dataclass(frozen=True)
class PayloadFieldView:
    """Typed owner for payload control projections used by helper flows."""

    fields: tuple[JsonObject, ...]

    @classmethod
    def from_payload(cls, payload: JsonObject) -> PayloadFieldView:
        raw_fields = payload.get(src.key_catalog.PK_CONTROLS)
        if not isinstance(raw_fields, list):
            return cls(fields=())
        return cls(
            fields=tuple(
                cast(JsonObject, raw)
                for raw in cast(list[object], raw_fields)
                if isinstance(raw, dict)
            )
        )

    def by_control_id(self) -> dict[str, JsonObject]:
        return {cid: fld for fld in self.fields if (cid := field_control_id(fld))}

    def current_values(self) -> dict[str, str | None]:
        return {
            cid: (
                current_value
                if isinstance(current_value := fld.get(PK_CURRENT_VALUE), str)
                else None
            )
            for fld in self.fields
            if (cid := field_control_id(fld))
        }


def write_action_target_value(action: JsonObject, value: JsonValue) -> None:
    """Set the operation-keyed value slot ("text" vs "expected_option") in place."""
    coerced = as_json_value(value)
    if action.get(PK_OPERATION) == OP_SET_TEXT:
        action[PK_TEXT] = coerced
    else:
        action[PK_EXPECTED_OPTION] = coerced


def action_display_value(action: JsonObject) -> JsonValue | None:
    operation = as_optional_string(action.get(PK_OPERATION)) or ""
    if operation == OP_SET_TEXT:
        return as_optional_string(action.get(PK_TEXT))
    if (
        operation in {OP_SELECT_OPTION, OP_SELECT_COMBOBOX, OP_CHOOSE_OPTION}
        and PK_EXPECTED_OPTION in action
    ):
        return action.get(PK_EXPECTED_OPTION)
    if operation == OP_SET_BOOLEAN:
        raw_value = action.get(PK_VALUE)
        if isinstance(raw_value, bool):
            return raw_value
    if operation == OP_UPLOAD_ATTACHMENT:
        return as_optional_string(action.get(PK_ATTACHMENT_SLOT))
    if PK_VALUE in action:
        return action.get(PK_VALUE)
    return None


def emit_status_events(
    adapter: PlannerToAGUIAdapter,
    update: PlannerStatusUpdate | Mapping[str, object],
) -> list[BaseEvent]:
    typed_update = (
        update
        if isinstance(update, PlannerStatusUpdate)
        else PlannerStatusUpdate.from_mapping(update)
    )
    logger.info(
        "agent_runner.emit_status_events",
        stage=typed_update.stage,
        status_level=typed_update.level,
    )
    return adapter.adapt_status_update(typed_update)


def extract_profile_result(payload: JsonObject) -> ProfileExtractionResult:
    profile_data = resolve_profile_data(payload)
    candidate = payload.get(PK_PROFILE_DATA)
    if isinstance(candidate, dict):
        return ProfileExtractionResult(profile_data=profile_data)
    if candidate is None:
        return ProfileExtractionResult(profile_data={})
    error = build_error_outcome(
        ValueError(
            "Profile payload was malformed; cloud helpers fell back to an empty profile."
        ),
        context={"profile_data_type": type(candidate).__name__},
        severity=src.key_catalog.SV_WARNING,
        recoverable=True,
        source="agent_runner.profile_extract",
        message="Profile payload was malformed; cloud helpers fell back to an empty profile.",
    ).to_payload()
    return ProfileExtractionResult(profile_data={}, error=error)


def extract_profile(payload: JsonObject) -> JsonObject:
    return extract_profile_result(payload).profile_data

from typing import Any

def identity(value: Any) -> Any:
    return value

"""Review-bundle verification result helpers for eval target finalization."""

from __future__ import annotations

import re
from collections import deque

import src.key_catalog
from src.key_catalog import PK_CONTROL_ID, PK_INTENT_ID, PK_REASON
from src.types.typed import (
    JsonObject,
    as_json_array,
    as_json_object,
    as_json_object_list,
    as_str,
)

from ...scoring import is_accepted_eval_skip
from ...types import ActionExecutionResult
from .state import PageLoopState

_US_ZIP_PATTERN = re.compile(r"\d{5}(?:-\d{4})?")
_UK_POSTCODE_EXAMPLE_PATTERN = re.compile(
    r"\b[A-Z]{1,2}\d[A-Z\d]?\s*\d[A-Z]{2}\b",
    re.IGNORECASE,
)
_UK_POSTCODE_MARKER_PATTERN = re.compile(
    r"\b(?:gb|great britain|uk|united kingdom)\b",
    re.IGNORECASE,
)


def _final_validity_accepts_verify_failures(after_validity: JsonObject) -> bool:
    return bool(after_validity.get("actionable_form_valid", False)) and bool(
        after_validity.get("non_system_form_valid", False),
    )


def _verification_result_passed(
    result: ActionExecutionResult,
    after_validity: JsonObject,
) -> bool:
    if result.passed or is_accepted_eval_skip(result):
        return True
    return (
        _final_validity_accepts_verify_failures(after_validity)
        and result.fill_ok
        and not result.verify_ok
        and result.reason == "verify_failed"
    )


def _is_us_zip_for_uk_postcode(
    result: ActionExecutionResult,
    state: PageLoopState,
) -> bool:
    field = next(
        (item for item in state.all_fields if item.control_id == result.control_id),
        None,
    )
    if field is None:
        return False
    label = field.question_text.casefold()
    uk_marked = "postcode" in label and bool(
        _UK_POSTCODE_MARKER_PATTERN.search(label)
        or _UK_POSTCODE_EXAMPLE_PATTERN.search(label)
    )
    value = result.expected_value
    return bool(
        uk_marked
        and isinstance(value, str)
        and _US_ZIP_PATTERN.fullmatch(value.strip())
    )


def _verification_result_payload(
    result: ActionExecutionResult,
    state: PageLoopState,
    after_validity: JsonObject,
) -> JsonObject:
    locale_incompatible = _is_us_zip_for_uk_postcode(result, state)
    reason = "locale_incompatible_value" if locale_incompatible else result.reason
    return as_json_object(
        {
            PK_CONTROL_ID: result.control_id,
            src.key_catalog.SV_PASSED: not locale_incompatible
            and _verification_result_passed(result, after_validity),
            PK_INTENT_ID: result.intent_id,
            "expected": result.expected_value,
            "observed": result.observed_value,
            PK_REASON: reason,
            "tool_error": not result.fill_ok,
        }
    )


def verification_results_from_state(
    state: PageLoopState,
    after_validity: JsonObject,
) -> list[JsonObject]:
    return [
        _verification_result_payload(result, state, after_validity)
        for result in state.all_execution_results
    ]


def _field_tool_calls(
    result: ActionExecutionResult,
    action: JsonObject,
    operation: str,
) -> list[JsonObject]:
    if result.skipped:
        return []
    return [
        as_json_object(
            {
                "tool_name": operation,
                src.key_catalog.ARG_ARGS: {
                    "value": action.get("value", result.expected_value)
                },
                "result_summary": result.reason,
                src.key_catalog.PK_SUCCESS: result.fill_ok,
                "error_message": None if result.fill_ok else result.reason,
                src.key_catalog.PK_DURATION_MS: result.elapsed_ms,
            }
        )
    ]


def _optional_text(value: object) -> str | None:
    if value is None:
        return None
    return str(value)


def _field_trace_payload(
    result: ActionExecutionResult,
    action: JsonObject,
    state: PageLoopState,
    after_validity: JsonObject,
    retry_count: int,
) -> JsonObject:
    operation = (
        as_str(action.get(src.key_catalog.PK_OPERATION), "")
        or result.widget_kind
        or "fill"
    )
    locale_incompatible = _is_us_zip_for_uk_postcode(result, state)
    verification_passed = (
        _verification_result_passed(result, after_validity) and not locale_incompatible
    )
    trace_reason = "locale_incompatible_value" if locale_incompatible else result.reason
    expected_state = _optional_text(result.expected_value)
    observed_after = _optional_text(result.observed_value)
    return as_json_object(
        {
            PK_CONTROL_ID: result.control_id,
            PK_INTENT_ID: result.intent_id,
            "fill_ok": result.fill_ok,
            "value_used": action.get("value", result.expected_value),
            "widget_kind": result.widget_kind or None,
            src.key_catalog.PK_QUESTION_TEXT: result.label or None,
            "decision_source": result.source,
            "intent_matched": bool(result.intent_id),
            "tool_calls": _field_tool_calls(result, action, operation),
            src.key_catalog.PK_OPERATION: operation,
            "execution_attempted": not result.skipped,
            src.key_catalog.PK_VERIFICATION_PASSED: None
            if result.skipped
            else verification_passed,
            "observed_after": observed_after,
            "expected_state": expected_state,
            "mismatch_reason": None
            if result.skipped or verification_passed
            else trace_reason,
            "verification_result": trace_reason,
            "skipped_due_to_condition": result.skipped,
            "retry_count": 0,
            src.key_catalog.PK_ERROR: None
            if result.skipped or result.fill_ok
            else result.reason,
        }
    )


def field_trace_payloads_from_state(
    state: PageLoopState,
    after_validity: JsonObject | None = None,
) -> list[JsonObject]:
    actions_by_control_id: dict[str, deque[JsonObject]] = {}
    for action in as_json_object_list(state.all_actions):
        actions_by_control_id.setdefault(
            as_str(action.get(PK_CONTROL_ID), ""), deque()
        ).append(action)
    validity = after_validity or {}
    traces: list[JsonObject] = []
    for result in state.all_execution_results:
        actions = actions_by_control_id.get(result.control_id)
        action = actions.popleft() if actions else {}
        traces.append(_field_trace_payload(result, action, state, validity))
    return traces


def summary_with_field_traces(
    summary: object,
    state: PageLoopState,
) -> JsonObject:
    result = as_json_object(summary)
    result[src.key_catalog.SK_FIELD_TRACES] = as_json_array(
        field_trace_payloads_from_state(state, state.after_validity)
    )
    return result


__all__ = [
    "field_trace_payloads_from_state",
    "summary_with_field_traces",
    "verification_results_from_state",
]

import type {
	Decision,
	HookEvent,
	HookResult,
	Platform,
	RuleFinding,
	Severity,
	SubprocessRun,
} from "@$REPO_SLOPGATE";

export interface SessionData {
	id: string;
	platform: Platform;
	eventCount: number;
	tools: string[];
	languages: string[];
	pathCount: number;
	finalOutcome: Decision;
	duration: number;
	events: HookEvent[];
	findings: RuleFinding[];
	results: HookResult[];
	subprocesses: SubprocessRun[];
}

export type TimelineFinding = {
	id: string;
	ruleId: string;
	severity: Severity;
	decision: Decision | null;
	message: string | null;
	additionalContext?: string | null;
};

export type TimelineEntry = {
	id: string;
	time: string;
	type: "event" | "finding" | "result" | "subprocess" | "hook";
	label: string;
	detail: string;
	sessionId: string;
	platform?: string;
	eventName?: string;
	toolName?: string;
	eventTime?: string;
	resultTime?: string;
	decision?: Decision;
	resultLabel?: string;
	resultDetail?: string;
	findingCount?: number;
	errorCount?: number;
	flagItemType: "event" | "finding" | "result" | "session";
	flagItemId: string;
	flagLabel: string;
	model?: string | null;
	provider?: string | null;
	command?: string | null;
	tool_output?: string | null;
	candidate_paths?: string[];
	tool_context?: string[];
	url_context?: string[];
	patch_text?: string | null;
	edit_before?: string | null;
	edit_after?: string | null;
	tool_input_json?: string | null;
	findings?: TimelineFinding[];
	correlation?: "matched" | "nearby" | "unmatched" | "historical-missing-input";
};

/**
 * Extracts candidate paths associated with a finding by checking its tool input
 * or correlating with matching session events close to its timestamp.
 */
function getPathsForFinding(finding: any, session: SessionData): string[] {
	const paths: string[] = [];

	// 1. Check tool_input in finding
	const toolInput = finding.tool_input || finding.metadata?.tool_input;
	if (toolInput) {
		const filePath = toolInput.file_path || toolInput.filePath || toolInput.path;
		if (typeof filePath === "string" && filePath.trim()) {
			paths.push(filePath.trim());
		}
	}

	// 2. Correlate with session events using tool_name and closest timestamp
	if (finding.tool_name) {
		const matchingEvents = session.events.filter(
			(e) => e.tool_name === finding.tool_name && e.candidate_paths?.length > 0,
		);
		if (matchingEvents.length > 0) {
			const findingTime = new Date(finding.timestamp).getTime();
			let bestEvent = matchingEvents[0];
			let minDiff = Number.POSITIVE_INFINITY;
			for (const e of matchingEvents) {
				const diff = Math.abs(new Date(e.timestamp).getTime() - findingTime);
				if (diff < minDiff) {
					minDiff = diff;
					bestEvent = e;
				}
			}
			if (bestEvent.candidate_paths) {
				paths.push(...bestEvent.candidate_paths);
			}
		}
	}

	return [...new Set(paths)].filter(Boolean);
}

/**
 * Returns the primary outcome cause for a session, prioritizing blocking/denying rules,
 * then advisory rules, and falling back to Clean allow.
 */
export function primarySessionCause(session: SessionData) {
	const allFindings: Array<{
		ruleId: string;
		severity: Severity;
		decision: Decision;
		message: string | null;
		timestamp: string;
		toolName?: string;
		eventName?: string;
		paths: string[];
	}> = [];

	// 1. Gather from session.findings
	for (const f of session.findings) {
		const decision = f.decision || "context";
		allFindings.push({
			ruleId: f.rule_id,
			severity: f.severity,
			decision,
			message: f.message,
			timestamp: f.timestamp,
			toolName: f.tool_name,
			eventName: f.event_name,
			paths: getPathsForFinding(f, session),
		});
	}

	// 2. Gather from session.results findings
	for (const r of session.results) {
		const findingsList = r.findings || [];
		for (const f of findingsList) {
			const decision = f.decision || "context";
			allFindings.push({
				ruleId: f.rule_id,
				severity: f.severity,
				decision,
				message: f.message,
				timestamp: r.timestamp,
				toolName: r.tool_name,
				eventName: r.event_name,
				paths: getPathsForFinding(
					{ ...f, timestamp: r.timestamp, tool_name: r.tool_name },
					session,
				),
			});
		}
	}

	const DECISION_PRIORITY: Record<Decision, number> = {
		block: 6,
		deny: 5,
		ask: 4,
		warn: 3,
		context: 2,
		info: 1,
		allow: 0,
	};

	const SEVERITY_PRIORITY: Record<Severity, number> = {
		CRITICAL: 4,
		HIGH: 3,
		MEDIUM: 2,
		LOW: 1,
	};

	const blockingFindings = allFindings.filter(
		(f) => f.decision === "block" || f.decision === "deny",
	);
	const advisoryFindings = allFindings.filter(
		(f) =>
			f.decision !== "block" &&
			f.decision !== "deny" &&
			f.decision !== "allow",
	);

	if (blockingFindings.length > 0) {
		blockingFindings.sort((a, b) => {
			const decDiff =
				DECISION_PRIORITY[b.decision] - DECISION_PRIORITY[a.decision];
			if (decDiff !== 0) return decDiff;
			const sevDiff =
				SEVERITY_PRIORITY[b.severity] - SEVERITY_PRIORITY[a.severity];
			if (sevDiff !== 0) return sevDiff;
			return b.timestamp.localeCompare(a.timestamp);
		});
		const primary = blockingFindings[0];
		return {
			decision: primary.decision,
			ruleId: primary.ruleId,
			severity: primary.severity,
			message: primary.message,
			eventName: primary.eventName,
			toolName: primary.toolName,
			path: primary.paths[0] || undefined,
			paths: primary.paths,
		};
	}

	if (advisoryFindings.length > 0) {
		advisoryFindings.sort((a, b) => {
			const decDiff =
				DECISION_PRIORITY[b.decision] - DECISION_PRIORITY[a.decision];
			if (decDiff !== 0) return decDiff;
			const sevDiff =
				SEVERITY_PRIORITY[b.severity] - SEVERITY_PRIORITY[a.severity];
			if (sevDiff !== 0) return sevDiff;
			return b.timestamp.localeCompare(a.timestamp);
		});
		const primary = advisoryFindings[0];
		return {
			decision: primary.decision,
			ruleId: primary.ruleId,
			severity: primary.severity,
			message: primary.message,
			eventName: primary.eventName,
			toolName: primary.toolName,
			path: primary.paths[0] || undefined,
			paths: primary.paths,
		};
	}

	// Fallback to error check if outcome is block/deny but no finding matched
	if (session.finalOutcome === "block" || session.finalOutcome === "deny") {
		const errorResult = session.results.find(
			(r) => r.errors && r.errors.length > 0,
		);
		if (errorResult) {
			return {
				decision: session.finalOutcome,
				message: errorResult.errors?.join(", ") || "Unknown session error",
				eventName: errorResult.event_name,
				toolName: errorResult.tool_name,
				paths: [],
			};
		}
	}

	return {
		decision: "allow" as Decision,
		message: "Clean allow",
		paths: [],
	};
}

/**
 * Returns a summary of agent activity in a session: last tool used, tool counts, event/path counts.
 */
export function sessionActivitySummary(session: SessionData) {
	const eventsWithTool = [...session.events]
		.filter((e) => e.tool_name)
		.sort((a, b) => a.timestamp.localeCompare(b.timestamp));
	const lastTool =
		eventsWithTool.length > 0
			? eventsWithTool[eventsWithTool.length - 1].tool_name
			: null;
	const uniqueTools = new Set(
		session.events.map((e) => e.tool_name).filter(Boolean),
	);
	return {
		lastTool,
		toolCount: uniqueTools.size,
		eventCount: session.events.length,
		pathCount: session.pathCount,
	};
}

/**
 * Selects the best initial timeline row to expand by default.
 */
export function initialTimelineSelection(
	entries: TimelineEntry[],
): string | null {
	if (entries.length === 0) return null;

	const blockDeny = entries.find(
		(e) => e.decision === "block" || e.decision === "deny",
	);
	if (blockDeny) return blockDeny.id;

	const withFindings = entries.find(
		(e) => (e.findingCount ?? 0) > 0 || e.type === "finding",
	);
	if (withFindings) return withFindings.id;

	const newestHook = entries.find((e) => e.type === "hook");
	if (newestHook) return newestHook.id;

	return entries[0].id;
}

/**
 * Returns user-friendly formatting details for a timeline entry.
 */
export function timelineRowSummary(entry: TimelineEntry) {
	let title = entry.label;
	let subtitle = entry.detail;
	const decisionLabel = entry.decision || "n/a";
	let primaryEvidenceLabel = "";

	if (entry.type === "hook") {
		title = `${entry.eventName} (${entry.toolName || "lifecycle"})`;
		subtitle = entry.detail;
		primaryEvidenceLabel = entry.findingCount
			? `${entry.findingCount} finding${entry.findingCount === 1 ? "" : "s"}`
			: "No findings";
		if (entry.errorCount) {
			primaryEvidenceLabel += `, ${entry.errorCount} error${
				entry.errorCount === 1 ? "" : "s"
			}`;
		}
	} else if (entry.type === "result") {
		title = `Result: ${entry.decision}`;
		subtitle = entry.detail;
		primaryEvidenceLabel = entry.findingCount
			? `${entry.findingCount} finding${entry.findingCount === 1 ? "" : "s"}`
			: "";
	} else if (entry.type === "finding") {
		title = entry.label;
		subtitle = entry.detail;
		primaryEvidenceLabel = entry.decision || "";
	} else if (entry.type === "subprocess") {
		title = entry.label;
		subtitle = entry.detail;
		primaryEvidenceLabel = entry.decision || "";
	}

	return {
		title,
		subtitle,
		decisionLabel,
		primaryEvidenceLabel,
	};
}

/**
 * Checks correlation status of a timeline entry.
 */
export function correlationStatus(
	entry: TimelineEntry,
): "matched" | "nearby" | "unmatched" | "historical-missing-input" {
	if (entry.type === "hook" || entry.correlation === "matched") {
		return "matched";
	}

	const isToolEvent =
		entry.eventName === "PreToolUse" || entry.eventName === "PostToolUse";
	const hasBody = Boolean(
		entry.command ||
			entry.tool_output ||
			entry.patch_text ||
			entry.edit_before ||
			entry.edit_after ||
			entry.tool_input_json,
	);

	if (entry.toolName && isToolEvent && !hasBody) {
		return "historical-missing-input";
	}

	if (entry.type === "result" || entry.correlation === "nearby") {
		const hasCorrelatedData = Boolean(
			entry.candidate_paths?.length ||
				entry.tool_context?.length ||
				entry.url_context?.length ||
				entry.model ||
				entry.provider,
		);
		return hasCorrelatedData ? "nearby" : "unmatched";
	}

	return "unmatched";
}

