from src.field.schema import ControlDescriptor
from src.types.typed import JsonObject

_RESEARCH_MANAGEMENT_FIELD: JsonObject = {
    "control_id": "research-manager-approach",
    "form_id": "ashby-application",
    "widget_kind": "textarea",
    "widget_family": "textarea",
    "question_text": (
        "If selected as a Research Manager, how would you ensure fellows "
