    "selector_hint": "#research-manager-approach",
}


def test_infer_missing_value_result_answers_preferred_name_na_instruction() -> None:
    field = ControlDescriptor.from_payload(
        {
            "control_id": "preferred-name",
            "form_id": "ashby-application",
            "widget_kind": "textbox",
            "widget_family": "textbox",
            "question_text": (
                "Do you have a preferred first and last name? If not, please type N/A"
            ),
            "labels": [
                "Do you have a preferred first and last name? If not, please type N/A"
            ],
            "required": True,
            "selector_hint": "#preferred-name",
        }
    )
    profile: JsonObject = {"personal": {"name": {"first": "Travis", "last": "Smith"}}}

    result = infer_missing_value_result(field, None, profile)

    assert result.value == "N/A"
    assert result.source == "heuristic_preferred_name_absent"


def test_infer_missing_value_result_explains_work_authorization_status() -> None:
    field = ControlDescriptor.from_payload(
        {
            "control_id": "work-auth-status",
            "form_id": "ashby-application",
            "widget_kind": "textarea",
            "widget_family": "textarea",
            "question_text": (
                "If you require employer sponsorship (H-1B, etc.) to legally work "
                "in the U.S., please explain your current work authorization status"
            ),
            "labels": [
                (
                    "If you require employer sponsorship (H-1B, etc.) to legally work "
                    "in the U.S., please explain your current work authorization status"
                )
            ],
            "required": True,
            "selector_hint": "#work-auth-status",
        }
    )
    profile: JsonObject = {
        "common_application_questions": {
            "authorized_to_work": "Yes",
            "require_sponsorship": "No",
        }
    }

    result = infer_missing_value_result(field, None, profile)

    assert result.value == (
        "I am authorized to work in the United States and do not require employer sponsorship."
    ), "authorization and sponsorship facts should produce the combined answer"
    assert result.path == "common_application_questions.authorized_to_work", (
        "the authorization fact should remain the provenance path"
    )
    assert result.source == "heuristic_work_authorization_status", (
        "the contextual authorization heuristic should identify its source"
    )


def test_infer_missing_value_result_answers_research_management_textarea() -> None:
    field = ControlDescriptor.from_payload(_RESEARCH_MANAGEMENT_FIELD)

    result = infer_missing_value_result(field, None, {})

    assert "milestones" in str(result.value).lower()
    assert "fellow" in str(result.value).lower()
    assert result.source == "heuristic_research_management_text"


def test_fallback_executes_required_research_management_textarea(
    ontology: IntentOntology,
) -> None:
    ctx = PlanCtx(
        profile_data={},
        params=AiPlanParams(
            ontology=ontology,
            budgets=PlannerBudgets(),
            platform="ashby",
        ),
    )
    actions, reviews = FallbackInferenceResolution.from_context(
        build_field_ctx(_RESEARCH_MANAGEMENT_FIELD),
        ctx,
    ).to_output(ctx)

    assert len(actions) == 1, (
        f"required research textarea should receive one draft action, got {actions!r}"
    )
    assert "fellow" in str(actions[0].value).lower()
    assert reviews, "required fallback draft should preserve review evidence"
    assert reviews[0].inference_source == "heuristic_research_management_text"


def test_field_loop_does_not_borrow_different_control_suggestion_by_index(
    ontology: IntentOntology,
) -> None:
    ctx = PlanCtx(
        profile_data={},
        params=AiPlanParams(ontology=ontology, budgets=PlannerBudgets()),
    )
    lookup = SuggestionLookup(
        by_field={},
        raw_list=[
            {
                "control_id": "different-control",
                "suggested_field_type": "unknown",
                "confidence": 0.99,
                "suggested_value": "borrowed wrong value",
            }
        ],
    )

    actions, _reviews = run_field_loop([_RESEARCH_MANAGEMENT_FIELD], lookup, ctx)

    assert len(actions) == 1, (
        f"missing same-control suggestion should use fallback action, got {actions!r}"
    )
    assert "milestones" in str(actions[0].value).lower()


def test_field_loop_does_not_borrow_idless_suggestion_by_index(
    ontology: IntentOntology,
) -> None:
    ctx = PlanCtx(
        profile_data={},
        params=AiPlanParams(ontology=ontology, budgets=PlannerBudgets()),
    )
    lookup = SuggestionLookup(
        by_field={},
        raw_list=[
            {
                "suggested_field_type": "unknown",
                "confidence": 0.99,
                "suggested_value": "borrowed wrong value",
            }
        ],
    )

    actions, _reviews = run_field_loop([_RESEARCH_MANAGEMENT_FIELD], lookup, ctx)

    assert len(actions) == 1, (
        f"id-less suggestion must use fallback action, got {actions!r}"
    )
    assert "borrowed wrong value" not in str(actions[0].value), (
        f"id-less suggestion must not attach by index: {actions!r}"
