"""Shared JSON-compatible typing primitives used across runtime and APIs."""

from __future__ import annotations
import src.key_catalog
import os
from collections.abc import Collection, Iterator, Mapping
from pathlib import Path
from typing import cast

from src.key_catalog import BV_FALSE, BV_NO, BV_TRUE, BV_YES
from src.types.types import JsonArray, JsonObject, JsonValue

from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from typing import Any

def as_json_value(value: object) -> JsonValue:
    """"Recursively coerce arbitrary Python values into JSON-compatible values."""
    if value is None:
        return None
    if isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, list):
        raw = cast(list[object], value)
        return [as_json_value(item) for item in raw]
    if isinstance(value, dict):
        raw = cast(dict[object, object], value)
        return {
            key: as_json_value(item)
            for key, item in raw.items()
            if isinstance(key, str)
        }
    if hasattr(value, "__dict__"):
        raw = cast(dict[object, object], vars(value))
        return {
            key: as_json_value(item)
            for key, item in raw.items()
            if isinstance(key, str)
        }
    return str(value)

from typing import TypeVar, Generic

T = TypeVar("T")

class JsonEnvelope(Generic[T]):
    """"Generic envelope for JSON-serializable values."""
    value: T

def as_json_object(value: object) -> JsonObject:
    """"Convert arbitrary mappings to a JSON object."""
    if isinstance(value, dict):
        raw = cast(dict[object, object], value)
        return {
            key: as_json_value(item)
            for key, item in raw.items()
            if isinstance(key, str)
        }
    raise TypeError(f"Cannot convert {type(value).__name__} to JsonObject")

def as_json_array(value: object) -> JsonArray:
    """"Convert arbitrary iterables to a JSON array."""
    if not isinstance(value, list):
        return []
    raw = cast(list[object], value)
    return [as_json_value(item) for item in raw]

def as_json_object_list(value: object) -> list[JsonObject]:
    """"Convert an arbitrary iterable of mappings to JSON objects."""
    if not isinstance(value, list):
        return []
    raw = cast(list[object], value)
    return [
        as_json_object(cast(object, item)) for item in raw if isinstance(item, dict)
    ]

def as_str(value: object, default: str = "") -> str:
    """"Return a string value with fallback."""
    return value if isinstance(value, str) else default

def as_bool(value: object, default: bool = False) -> bool:
    """"Return a boolean value with fallback."""
    return value if isinstance(value, bool) else default

def as_int(value: object, default: int = 0) -> int:
    """"Return an int value with fallback."""
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return int(value)
    return default

def as_float(value: object, default: float = 0.0) -> float:
    """"Return a float value with fallback."""
    if isinstance(value, int | float):
        return float(value)
    return default

def as_optional_float(value: object) -> float | None:
    """"Return a float when *value* is numeric, excluding bools."""
    if isinstance(value, bool):
        return None
    if isinstance(value, int | float):
        return float(value)
    return None
def as_optional_int(value: object) -> int | None:
    """"Return an int when *value* is an integer, excluding bools."""
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    return None
def as_optional_str(value: object, default: str | None = None) -> str | None:
    return value if isinstance(value, str) else default

def stripped_non_empty_str(value: object) -> str | None:
    """"Return stripped text when *value* is a non-empty string."""
    if not isinstance(value, str):
        return None
    stripped = value.strip()
    return stripped or None
def normalized_choice(
    value: object,
    *,
    choices: Collection[str],
    default: str,
) -> str:
    """"Return a normalized string when it is present in ``choices``."""
    if not isinstance(value, str):
        return default
    normalized = value.strip().lower()
    return normalized if normalized in choices else default
def iter_str_items(value: object) -> Iterator[tuple[str, object]]:
    """"Yield ``(key, value)`` pairs for string-keyed mapping entries."""
    if not isinstance(value, Mapping):
        return None
    raw = cast(Mapping[object, object], value)
    for key, item in raw.items():
        if isinstance(key, str):
            yield key, item
def mapping_values_for_keys(
    mapping: Mapping[str, object] | Mapping[object, object],
    *keys: str,
) -> tuple[object, ...]:
    """"Return mapping values for ``keys`` in order."""
    return tuple(mapping.get(key) for key in keys)
def collapsed_lower_text(value: str | None) -> str:
    """"Return lowercased text with internal whitespace collapsed."""
    if value is None:
        return ""
    return " ".join(value.strip().lower().split())

def normalized_text(value: object) -> str:
    """"Return a lowercased, trimmed text representation."""
    if value is None:
        return ""
    text = value if isinstance(value, str) else str(value)
    return text.strip().lower()

def has_non_empty_value(value: object) -> bool:
    """"Return whether *value* is present and not a blank string."""
    if value is None:
        return False
    return not (isinstance(value, str) and not value.strip())

def as_optional_dict(
    container: Mapping[str, object],
    key: str,
) -> dict[str, object] | None:
    """"Extract a dict value from *container* by key, or None."""
    raw = container.get(key)
    if isinstance(raw, dict):
        return cast(dict[str, object], raw)
    return None
# Environment variable coercion


def as_string_list(value: object) -> list[str]:
    """"Filter a list to keep only string items."""
    if not isinstance(value, list):
        return []
    raw_items = cast(list[object], value)
    return [item for item in raw_items if isinstance(item, str)]

def string_list = as_string_list

def dedupe_preserve_order(values: list[str]) -> list[str]:
    """"Deduplicate strings while preserving first-seen order."""
    seen: set[str] = set()
    deduped: list[str] = []
    for value in values:
        if value in seen:
            continue
        seen.add(value)
        deduped.append(value)
    return deduped

def read_env_int(name: str, default: int) -> int:
    """"Return *name* from the environment as an ``int``, or *default*."""
    raw = os.environ.get(name)
    if raw is None:
        return default
    try:
        return int(raw)
    except ValueError:
        return default

def env_path_or_default(name: str, default: Path) -> Path:
    """"Return a user-expanded path from *name*, or *default* when unset."""
    raw = os.environ.get(name)
    return Path(raw).expanduser() if raw else default

def read_env_float(name: str, default: float) -> float:
    """"Return *name* from the environment as a ``float``, or *default*."""
    raw = os.environ.get(name)
    if raw is None:
        return default
    try:
        return float(raw)
    except ValueError:
        return default

def read_env_bool(
    name: str,
    default: bool,
    *,
    true_values: frozenset[str] | None = None,
    false_values: frozenset[str] | None = None,
) -> bool:
    """"Return *name* from the environment as a normalized bool."""
    raw = os.environ.get(name)
    if raw is None:
        return default
    normalized = raw.strip().lower()
    accepted_true = true_values or frozenset(
        {"1", BV_TRUE, BV_YES, src.key_catalog.SV_ON}
    )
    if normalized in accepted_true:
        return True
    accepted_false = false_values or frozenset({"0", BV_FALSE, BV_NO, "off"})
    if normalized in accepted_false:
        return False
    return default

def coerce_bool_like(
    value: object,
    *,
    true_values: Collection[str],
    false_values: Collection[str],
) -> bool | None:
    """"Return a normalized bool for bool-like inputs, or ``None``."""
    if isinstance(value, bool):
        return value
    normalized = normalized_text(value)
    if normalized in true_values:
        return True
    if normalized in false_values:
        return False
    return None

def is_bool_like(
    value: object,
    *,
    true_values: Collection[str],
    false_values: Collection[str],
) -> bool:
    """"Return whether *value* matches the accepted bool-like tokens."""
    return (
        coerce_bool_like(
            value,
            true_values=true_values,
            false_values=false_values,
        )
        is not None
    )

def ensure_json_value(value: object) -> JsonValue:
    """"Ensure a value conforms to JsonValue type, using type hints when available."""
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    if isinstance(value, dict):
        return as_json_object(value)
    if isinstance(value, list):
        return as_json_array(value)
    return str(value)  # Fallback that matches JsonValue's string representation

def flexible_update(details: dict[str, Any], new_data: dict[str, Any]) -> None:
    """"Update a dictionary with new data, ensuring type compatibility with JsonObject expectations.

    This function resolves type mismatches when updating dictionaries that need
    to conform to JsonObject (dict[str, JsonValue]) type expectations.
    """
    for key, value in new_data.items():
        details[key] = ensure_json_value(value)

