 'model.provider','model.default','model.base_url','agent.max_turns','agent.api_max_retries',
 'agent.gateway_timeout','agent.gateway_timeout_warning','agent.reasoning_effort','agent.service_tier',
 'terminal.backend','terminal.cwd','terminal.timeout','terminal.persistent_shell','terminal.ssh.host',
 'terminal.ssh.user','terminal.ssh.port','tool_loop_guardrails.warnings_enabled',
 'tool_loop_guardrails.hard_stop_enabled','compression.enabled','compression.threshold',
 'auxiliary.vision.provider','auxiliary.vision.model','auxiliary.vision.timeout',
 'auxiliary.web_extract.provider','auxiliary.web_extract.model','auxiliary.web_extract.timeout',
 'auxiliary.compression.provider','auxiliary.compression.model','auxiliary.compression.timeout',
 'auxiliary.mcp.provider','auxiliary.mcp.model','auxiliary.mcp.timeout',
 'delegation.provider','delegation.model','delegation.child_timeout_seconds',
 'memory.provider','browser.command_timeout','browser.inactivity_timeout','browser.dialog_timeout_s',
]

def get(d, path, default='—'):
    cur=d
    for k in path.split('.'):
        if not isinstance(cur, dict) or k not in cur: return default
        cur=cur[k]
    if path.endswith('base_url') and isinstance(cur,str) and cur:
        s=urlsplit(cur)
        return f'{s.scheme}://{s.netloc}{s.path}'
    return cur if cur not in ('', None) else '—'

for name, home in homes:
    cfg=yaml.safe_load((home/'config.yaml').read_text()) or {}
    print(f'[{name}]')
    for path in paths:
        print(f'{path}={get(cfg,path)}')
    providers=cfg.get('providers') or {}
    for pid,pv in providers.items():
        if not isinstance(pv,dict): continue
        vals=[]
        for k in ('request_timeout_seconds','stale_timeout_seconds'):
            if k in pv: vals.append(f'{k}={pv[k]}')
        for mid,mv in (pv.get('models') or {}).items():
            if isinstance(mv,dict):
                for k in ('timeout_seconds','stale_timeout_seconds'):
                    if k in mv: vals.append(f'models.{mid}.{k}={mv[k]}')
        if vals: print(f'providers.{pid}: '+', '.join(vals))
    mcp=cfg.get('mcp_servers') or {}
    enabled={k:v for k,v in mcp.items() if not isinstance(v,dict) or v.get('enabled',True)}
    print('mcp.enabled='+(','.join(enabled) if enabled else '—'))
    for mid,mv in enabled.items():
        if isinstance(mv,dict): print(f'mcp.{mid}.connect_timeout={mv.get("connect_timeout","default")}')
    print('skills.files='+str(sum(1 for p in (home/'skills').rglob('*') if p.is_file()) if (home/'skills').exists() else 0))
    env={}
    ep=home/'.env'
    if ep.exists():
        for raw in ep.read_text(errors='replace').splitlines():
            line=raw.strip()
            if not line or line.startswith('#') or '=' not in line: continue
            k,v=line.split('=',1); env[k.strip()]=v.strip().strip('"').strip("'")
    for k in sorted(env):
        if any(x in k for x in ('TIMEOUT','STALE','RETRY','BASE_URL','MODEL','PROVIDER','SSH_HOST','SSH_USER','SSH_PORT')) and not any(x in k for x in ('PASSWORD','TOKEN','KEY','SECRET')):
            print(f'env.{k}={env[k]}')
