def _relaid(panel: AgentTracePanel, settled: dict[str, EntryLayout]) -> list[str]:
    """Entries whose layout object was rebuilt since the snapshot."""
    return [key for key in settled if panel._state.layouts[key] is not settled[key]]


def _settled(
    panel: AgentTracePanel,
) -> tuple[dict[str, EntryLayout], dict[str, list[StripKey]]]:
    """The panel's laid-out entries and the cache keys covering each of them."""
    layouts = dict(panel._state.layouts)
    return layouts, {key: _cached_line_keys(panel, key) for key in layouts}


async def _seed_count(
    panel: AgentTracePanel, pilot: Pilot[None], count: int
) -> None:
    """Seed ``count`` reasoning entries from a clean transcript."""
    await _seed(panel, pilot, _entries(count))


async def _append(
    panel: AgentTracePanel, pilot: Pilot[None], *entries: AgentTraceEntry
) -> None:
    """Extend the current snapshot with ``entries`` and settle one frame."""
    await _seed(panel, pilot, (*panel.data.entries, *entries))


async def _scroll_away(panel: AgentTracePanel, pilot: Pilot[None], row: int = 5) -> None:
    """Leave the live tail at ``row`` and settle the frame."""
    panel.scroll_to(y=row, animate=False, force=True)
    await pilot.pause()


async def _press_end(panel: AgentTracePanel, pilot: Pilot[None]) -> None:
    """Take the explicit end gesture on a focused panel."""
    panel.focus()
    await pilot.press("end")
    await pilot.pause()


def _row_text(panel: AgentTracePanel, row: int) -> str:
    """The painted text of one viewport row."""
    return panel.render_line(row).text


def _replace_first(
    panel: AgentTracePanel, entry_id: str, content: str, revision: int
) -> AgentTraceEntry:
    """A revised copy of an entry, keeping its identity position."""
    return AgentTraceEntry(
        kind=TRACE_REASONING,
        title="step 0",
        content=content,
        entry_id=entry_id,
        revision=revision,
    )


def _metrics(
    panel: AgentTracePanel, entry: AgentTraceEntry
) -> tuple[EntryLayout, object, int]:
    """The entry's layout, its wrapped source line, and expected line count."""
    layout = panel._state.layouts[entry.entry_id]
    source = entry_source_lines(entry)[-1]
    return layout, source, -(-source.cell_len // panel._state.layout_width)


def _rendered_body(panel: AgentTracePanel, entry: AgentTraceEntry) -> str:
    """Every painted content row of one entry, joined in visual-line order."""
    layout = panel._state.layouts[entry.entry_id]
    top = panel._state.row_starts[panel._state.index[entry.entry_id]]
    return "".join(
        strip_for_row(panel._state, _paint(panel), top + 1 + offset).text.rstrip()
        for offset in range(1, layout.line_count)
    )

