"""Property-based coverage for Langfuse observation naming (Hypothesis)."""

from __future__ import annotations

import pytest
from hypothesis import given, settings
from hypothesis import strategies

from cloud.services.agent_runner.langfuse.labels import event_observation_name
from src.agui import BaseEvent, PhaseMessageEvent

pytestmark = [pytest.mark.unit]

ACRONYM_TOKENS = strategies.sampled_from(
    ["llm", "jd", "ats", "url", "id", "api", "cdp", "ui", "pdf"]
)
PLAIN_TOKENS = strategies.sampled_from(
    ["field", "focus", "verify", "retry", "stage", "started", "finished"]
)


@given(tokens=strategies.lists(ACRONYM_TOKENS, min_size=1, max_size=5))
@settings(max_examples=30, deadline=None)
def test_observation_name_preserves_acronym_tokens(tokens: list[str]) -> None:
    event = BaseEvent(type="_".join(tokens))

    name = event_observation_name(event)

    assert name[:1].isupper(), f"name should start capitalized: {name}"
    for token in tokens:
        assert token.upper() in name, f"acronym {token.upper()!r} missing: {name!r}"


@given(tokens=strategies.lists(PLAIN_TOKENS, min_size=1, max_size=5))
@settings(max_examples=30, deadline=None)
def test_observation_name_lowercases_plain_tokens(tokens: list[str]) -> None:
    event = BaseEvent(type="_".join(tokens))

    name = event_observation_name(event)

    assert name[:1].isupper(), f"name should start capitalized: {name}"
    for token in tokens:
        assert token in name, f"plain token {token!r} missing: {name!r}"


@given(phase=strategies.sampled_from(["plan", "execute", "review"]))
@settings(max_examples=20, deadline=None)
def test_phase_message_name_appends_phase_in_parentheses(phase: str) -> None:
    event = PhaseMessageEvent(phase=phase)

    name = event_observation_name(event)

    assert name.startswith("Phase message"), f"base name wrong: {name!r}"
    assert name.endswith(f"({phase})"), f"phase suffix missing: {name!r}"

