from pathlib import Path

import pytest

from automation.scripts.eval import dataset_sampler
from automation.scripts.eval.dataset_sampler import SampledJob
from src.types.typed import JsonObject


class RowsTable:
    """Minimal parquet table double returning canned rows."""

    def __init__(self, rows: list[JsonObject]) -> None:
        self._rows = rows

    def __len__(self) -> int:
        return len(self._rows)

    def slice(self, offset: int, length: int) -> RowsTable:
        if offset < 0 or length != 1:
            raise AssertionError("sampler should request one nonnegative row slice")
        return RowsTable(self._rows[offset : offset + length])

    def to_pylist(self) -> list[JsonObject]:
        return list(self._rows)


def sample_rows(
    monkeypatch: pytest.MonkeyPatch,
