        assert (path, columns) == ("jobs.parquet", None), (
            "sampling should read the requested parquet with all columns"
        )
        return RowsTable(rows)

    monkeypatch.setattr(
        "automation.scripts.eval.dataset_sampler._read_parquet",
        fake_read_parquet,
    )
    return dataset_sampler.sample_apply_urls(
        Path("jobs.parquet"), "greenhouse", count=count, seed=0
    )


__all__ = ["RowsTable", "sample_rows"]

