tool_input.content:
"""Regression tests for the interrupt cycle limit guard.

The bounded pause/resume loop must terminate the run with a
``RUN_ERROR`` carrying ``InterruptCycleLimitExceeded`` and never reach
``RUN_FINISHED`` or a submit click, even when the graph keeps pausing on
the same control. This guards the "token burn" class of failure: without
the cycle limit, repeated operator approval loops the planner indefinitely.
"""

from __future__ import annotations

from collections.abc import Callable
from typing import cast

import pytest

from cloud.services.agent_runner import (
    AgentStreamConfig,
    run_agent_stream,
)
from cloud.services.agent_runner._contracts import (
    PauseResult,
)
from cloud.services.agent_runner.lifecycle_streaming import (
    stream_graph_loop,
)
from cloud.services.agent_runner_support.interrupts import (
    InterruptCycleLimitExceeded,
)
from cloud.services.checkpointer import (
    InterruptManager,
    ResolveInterruptRequest,
)
from src.agui import PlannerToAGUIAdapter
from src.types.typed import JsonObject

_CYCLE_RUN_ID = "runtime-cycle-guard"
_CYCLE_FIELD = "field_a"
_CYCLE_LIMIT = 0
_CYCLE_TIMEOUT = 0.5
_REVIEW_REASON = "low_confidence"


def _pause_result_payload() -> dict[str, object]:
    """Plan result used as a starter; the graph is faked downstream so
    this result is never inspected by the cycle-limit test."""
    return {
        "actions": [],
        "review_items": [
            {
                "control_id": _CYCLE_FIELD,
                "reason": _REVIEW_REASON,
                "value": None,
            }
        ],
    }


def _build_config(manager: InterruptManager) -> AgentStreamConfig:
    """Build a minimal AgentStreamConfig with the cycle limit engaged."""
    adapter = PlannerToAGUIAdapter(
        request_id=_CYCLE_RUN_ID, plan_id=_CYCLE_RUN_ID
    )
    return AgentStreamConfig(
        payload=cast(JsonObject, {}),
        adapter=adapter,
        interrupt_manager=manager,
        starting_sequence=0,
        interrupt_timeout_seconds=_CYCLE_TIMEOUT,
        interrupt_cycle_limit=_CYCLE_LIMIT,
    )


def _seed_resume_cycle(manager: InterruptManager) -> None:
    """Pre-request a resolved interrupt and re-seed the resume payload
    so the lifecycle can keep cycling until the cycle limit fires."""
    manager.request_interrupt(
        _CYCLE_RUN_ID, _CYCLE_FIELD, _REVIEW_REASON, None
    )
    manager.resolve_interrupt_result(
        ResolveInterruptRequest(
            run_id=_CYCLE_RUN_ID,
            control_id=_CYCLE_FIELD,
            decision="approved",
        )
    )
    manager.resume_payloads[_CYCLE_RUN_ID] = {
        "decisions": {_CYCLE_FIELD: "approved"},
    }


def _install_repeatable_resume(
    monkeypatch: pytest.MonkeyPatch, manager: InterruptManager
) -> None:
    """Re-seed the resume payload on every wait so the lifecycle loop
    is not interrupted by ``InterruptWaitTimedOut``."""

    async def always_return_payload(
        _run_id: str, _timeout_seconds: float = 60.0, **kwargs: object
    ) -> object:
        return cast(
            object,
            {"decisions": {_CYCLE_FIELD: "approved"}},
        )

    monkeypatch.setattr(manager, "wait_for_resume", always_return_payload)


def _install_always_pause(monkeypatch: pytest.MonkeyPatch) -> None:
    """Replace ``stream_graph_loop`` with a function that always returns
    a PauseResult for the cycle-limited control. This is the minimum
    seam needed to drive the cycle counter through repeated pauses."""

    async def always_pause(
        _cfg: object, _invocation: object, _run_ctx: object
    ) -> PauseResult:
        return PauseResult(pending_control_ids=(_CYCLE_FIELD,))

    monkeypatch.setattr(
        "cloud.services.agent_runner.lifecycle_streaming.stream_graph_loop",
        always_pause,
    )
    # The plain (non-lifecycle) alias used by stream_graph_to_result.
    # _stream_loop also imports stream_graph_loop at module level.
    monkeypatch.setattr(
        "cloud.services.agent_runner._stream_loop.stream_graph_loop",
        always_pause,
    )


def _event_type(chunk: str) -> str:
    """Extract the AG-UI event type from a serialized SSE chunk."""
    from cloud.routers.agent_stream.sse import SSEFrame

    return SSEFrame.parse(chunk).event_type or ""


def _error_details(chunk: str) -> dict[str, object]:
    """Extract the ``details`` field from a RUN_ERROR SSE chunk."""
    from cloud.routers.agent_stream.sse import SSEFrame

    payload = SSEFrame.parse(chunk).payload or {}
    details = payload.get("details", {})
    if not isinstance(details, dict):
        return {}
    return cast(dict[str, object], details)


def _assert_cycle_limit_surface(event_types: list[str], error_chunk: str) -> None:
    """Assert the SSE block stream contains a proper cycle-limit
    RUN_ERROR and no RUN_FINISHED."""
    assert "RUN_STARTED" in event_types, (
        f"stream should start with RUN_STARTED; saw {event_types}"
    )
    assert "RUN_ERROR" in event_types, (
        f"stream should terminate with RUN_ERROR; saw {event_types}"
    )
    assert "RUN_FINISHED" not in event_types, (
        f"cycle limit must not produce RUN_FINISHED; saw {event_types}"
    )
    details = _error_details(error_chunk)
    assert details.get("cycle_limit") == _CYCLE_LIMIT, (
        f"RUN_ERROR must surface cycle_limit, got {details.get('cycle_limit')!r}"
    )
    assert "cycle_count" in details, (
        f"RUN_ERROR details missing cycle_count: {details}"
    )
    assert details.get("pending_control_ids") == [_CYCLE_FIELD], (
        f"RUN_ERROR must surface pending_control_ids, "
        f"got {details.get('pending_control_ids')!r}"
    )


def _assert_no_submit_events(events: list[str]) -> None:
    """Assert no submit-related event appears anywhere in the stream."""
    for chunk in events:
        if "submit_confirmed" in chunk or "submit_authorization" in chunk:
            pytest.fail(f"submit-related event leaked into stream: {chunk}")


_MakeStubPlanner = Callable[..., object]
_PatchPlannerSubgraph = Callable[[pytest.MonkeyPatch, object], None]


async def test_repeated_interrupt_hits_cycle_limit_without_submit(
    monkeypatch: pytest.MonkeyPatch,
    make_stub_planner: _MakeStubPlanner,
    patch_planner_subgraph: _PatchPlannerSubgraph,
) -> None:
    """End-to-end: when the graph keeps pausing on the same control, the
    stream must terminate with RUN_ERROR + InterruptCycleLimitExceeded and
    never reach RUN_FINISHED or a submit click."""
    from tests.agent_stream._fixtures.stream_client import (
        patch_noop_executor_backend,
    )

    manager = InterruptManager()
    _seed_resume_cycle(manager)
    _install_repeatable_resume(monkeypatch, manager)
    _install_always_pause(monkeypatch)

    stub = make_stub_planner(_pause_result_payload())
    patch_planner_subgraph(monkeypatch, stub)
    cfg = _build_config(manager)

    with patch_noop_executor_backend():
        events = [
            chunk
            async for chunk in run_agent_stream(cfg)
        ]

    event_types = [_event_type(e) for e in events]
    error_chunk = next(
        e for e in events if _event_type(e) == "RUN_ERROR"
    )
    _assert_cycle_limit_surface(event_types, error_chunk)
    _assert_no_submit_events(events)


async def test_repeated_interrupt_exception_carries_cycle_metadata() -> None:
    """Sanity: the exception type carries cycle_count / cycle_limit /
    pending_control_ids the test relies on."""
    exc = InterruptCycleLimitExceeded(
        run_id=_CYCLE_RUN_ID,
        cycle_count=1,
        cycle_limit=_CYCLE_LIMIT,
        pending_control_ids=(_CYCLE_FIELD,),
    )
    assert exc.cycle_count == 1
    assert exc.cycle_limit == _CYCLE_LIMIT
    assert exc.pending_control_ids == (_CYCLE_FIELD,)

