ld{border-bottom:0}.dashboard-system-list span{display:flex;align-items:center;gap:9px;color:#565d6c;font-size:11px}.dashboard-system-list span>i{width:27px;height:27px;display:grid;place-items:center;color:#747b8b;background:#f1f3f6;border-radius:7px}.dashboard-system-list strong{color:#333946;font-size:10px}.dashboard-system-list .system-online{color:#23805a}.system-online>i{display:inline-block;width:7px;height:7px;margin-right:5px;background:#31b477;border-radius:50%;box-shadow:0 0 0 3px #ddf5ea}
