}
#page-inner .admin-directory-page .dataTables_info,
#page-inner .admin-notification-page .dataTables_info {
    color: var(--admin-secondary);
    font-size: 13px;
}
#page-inner .admin-directory-page .dataTables_paginate .pagination > li > a,
#page-inner .admin-notification-page .dataTables_paginate .pagination > li > a,
#page-inner .admin-directory-page .dataTables_paginate .pagination > li > span,
#page-inner .admin-notification-page .dataTables_paginate .pagination > li > span {
