}
#page-inner .admin-directory-page .dataTables_paginate .pagination > .active > a,
#page-inner .admin-notification-page .dataTables_paginate .pagination > .active > a {
    background: var(--admin-navy);
    border-color: var(--admin-navy);
    color: #fff;
}
#page-inner .admin-directory-page .dataTables_paginate .pagination > .disabled > a,
#page-inner .admin-notification-page .dataTables_paginate .pagination > .disabled > a,
#page-inner .admin-directory-page .dataTables_paginate .pagination > .disabled > span,
#page-inner .admin-notification-page .dataTables_paginate .pagination > .disabled > span {
    color: var(--admin-secondary);
}
.admin-directory-page details,
.admin-notification-page details {
    margin: 0 0 8px;
    background: #fff;
    border: 1px solid var(--admin-border);
    border-radius: 4px;
}
.admin-directory-page summary,
.admin-notification-page summary {
    display: flex;
    align-items: center;
    gap: 8px;
    min-height: 44px;
    padding: 10px 12px;
    font-weight: 700;
    color: var(--admin-navy);
    cursor: pointer;
}
.admin-directory-page summary::-webkit-details-marker,
.admin-notification-page summary::-webkit-details-marker {
    display: none;
}
.admin-directory-page details[open] > summary,
.admin-notification-page details[open] > summary {
    border-bottom: 1px solid var(--admin-border);
}
.admin-directory-page details > form,
.admin-notification-page details > form,
.admin-directory-page details > .admin-technical-details,
.admin-notification-page details > .admin-technical-details {
    padding: 12px;
}
.admin-directory-page .admin-technical-details,
.admin-notification-page .admin-technical-details {
    min-width: 0;
    overflow-wrap: anywhere;
}
.admin-directory-page .admin-technical-details dl,
.admin-notification-page .admin-technical-details dl {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: 8px;
    margin: 0;
}
.admin-directory-page .admin-technical-details dt,
.admin-notification-page .admin-technical-details dt {
    font-size: 14px;
    font-weight: 700;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    color: var(--admin-secondary);
}
.admin-directory-page .admin-technical-details dd,
.admin-notification-page .admin-technical-details dd {
    margin: 0;
    font-size: 13px;
    overflow-wrap: anywhere;
    word-break: break-word;
}
.admin-directory-page .admin-technical-details code,
.admin-notification-page .admin-technical-details code,
.admin-directory-page .admin-technical-details pre,
.admin-notification-page .admin-technical-details pre {
    padding: 8px;
    border: 1px solid var(--admin-border);
    border-radius: 4px;
    background: var(--admin-bg);
    color: #343946;
    font-size: 14px;
    white-space: pre-wrap;
    word-break: break-all;
}
.admin-directory-page .admin-empty-state,
.admin-notification-page .admin-empty-state {
    margin: 0 0 16px;
    padding: 24px 16px;
    background: #fff;
    border: 1px solid var(--admin-border);
    border-radius: 4px;
    color: var(--admin-secondary);
    text-align: center;
    overflow-wrap: anywhere;
}
.admin-directory-page .admin-empty-state > :last-child,
.admin-notification-page .admin-empty-state > :last-child {
    margin-bottom: 0;
}
.admin-directory-page .admin-empty-state p,
.admin-notification-page .admin-empty-state p {
    margin: 0 0 12px;
    color: var(--admin-secondary);
}
.admin-directory-page .alert,
.admin-notification-page .alert {
    margin: 0 0 16px;
    padding: 12px 16px;
    border: 1px solid transparent;
    border-radius: 4px;
    font-size: 14px;
    line-height: 1.55;
    overflow-wrap: anywhere;
}
.admin-directory-page .alert-danger,
.admin-notification-page .alert-danger {
    color: #a5222e;
    background: #ffe5e8;
    border-color: #f0bcc3;
}
.admin-directory-page .alert-success,
.admin-notification-page .alert-success {
    color: #176542;
    background: #def5e9;
    border-color: #b9e4d0;
}
.admin-directory-page .alert-warning,
.admin-notification-page .alert-warning {
    color: #8a620d;
    background: #fff1c9;
    border-color: #ead9a6;
}
.admin-directory-page .alert-info,
.admin-notification-page .alert-info {
    color: #5b6170;
    background: #edf0f4;
    border-color: #d8dee6;
}
@media (max-width: 767px) {
    #page-inner .admin-directory-page h1,
    #page-inner .admin-notification-page h1 {
        font-size: 25px;
    }
    #page-inner .admin-directory-page input.form-control,
    #page-inner .admin-notification-page input.form-control,
    #page-inner .admin-directory-page select.form-control,
    #page-inner .admin-notification-page select.form-control,
    #page-inner .admin-directory-page textarea.form-control,
    #page-inner .admin-notification-page textarea.form-control {
        font-size: 16px;
    }
    .admin-directory-page .admin-operation-panel,
    .admin-notification-page .admin-operation-panel {
        margin-bottom: 16px;
        padding: 16px;
    }
    .admin-directory-page .admin-page-tabs a,
    .admin-notification-page .admin-page-tabs a {
        flex: 1 1 100%;
    }
}
@media (min-width: 768px) {
    .admin-directory-page .admin-operation-panel,
    .admin-notification-page .admin-operation-panel {
        padding: 24px;
    }
}
@media (prefers-reduced-motion: reduce) {
    .admin-directory-page *,
    .admin-notification-page * {
        transition: none !important;
        animation: none !important;
        scroll-behavior: auto !important;
    }
}
#page-inner .admin-directory-page .admin-edit-form,
#page-inner .admin-notification-page .admin-edit-form { display: block; width: 100%; margin: 0 0 24px; }
.admin-directory-page .admin-row-summary,
.admin-notification-page .admin-row-summary { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; margin: 0 0 16px; }
.admin-directory-page .admin-row-summary strong,
.admin-notification-page .admin-row-summary strong { display: block; font-size: 26px; }
.admin-directory-page .dashboard-header > div,
.admin-notification-page .dashboard-header > div { min-width: 0; flex: 1 1 320px; }
.admin-directory-page,
.admin-notification-page { overflow-wrap: anywhere; }
@media (max-width: 767px) {
    .admin-directory-page .admin-row-summary,
    .admin-notification-page .admin-row-summary { grid-template-columns: minmax(0, 1fr); }
}


/* Shipping administration */
.admin-shipping-page {
    width: 100%;
    max-width: 1180px;
    min-width: 0;
    overflow-wrap: anywhere;
}

.admin-shipping-page p {
    padding: 0;
}

.admin-shipping-page:not(.is-enhanced) .admin-shipping-enhancement-only {
    display: none;
}

.admin-shipping-page a:focus,
.admin-shipping-page button:focus,
.admin-shipping-page input:focus,
.admin-shipping-page select:focus,
.admin-shipping-page textarea:focus,
.admin-shipping-page summary:focus,
.admin-shipping-page [tabindex]:focus {
    outline: 3px solid var(--admin-navy);
    outline-offset: 3px;
}

.admin-shipping-page .dashboard-header {
    flex-wrap: wrap;
    gap: 16px;
}

.admin-shipping-page .dashboard-header > div {
    flex: 1 1 420px;
    min-width: 0;
}

.admin-shipping-page .admin-operation-panel {
    min-width: 0;
    margin-bottom: 24px;
    padding: 24px;
}

#page-inner .admin-shipping-page .admin-edit-form {
    display: block;
    width: 100%;
    max-width: none;
    margin: 0;
}

#page-inner .admin-shipping-page fieldset.admin-form-section,
.admin-shipping-page section.admin-form-section {
    min-width: 0;
    margin: 0 0 20px;
    padding: 20px;
    border: 1px solid var(--admin-border);
    border-radius: 8px;
}

#page-inner .admin-shipping-page legend {
    width: auto;
    margin: 0 0 12px;
    padding-right: 8px;
    border: 0;
    color: var(--admin-navy);
}

#page-inner .admin-shipping-page .form-group {
    float: none;
    clear: both;
    width: 100%;
    max-width: none;
    margin: 0 0 18px;
    padding: 0;
    border: 0;
}

.admin-shipping-page .help-block,
.admin-shipping-page .admin-shipping-band-count,
.admin-shipping-page .admin-shipping-selection-summary small,
.admin-shipping-page caption {
    color: var(--admin-muted);
}

.admin-shipping-page .admin-field-error {
    display: block;
    margin-top: 6px;
    color: var(--admin-red);
}

.admin-shipping-page .admin-checkbox-row {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    min-height: 44px;
    margin: 0;
    padding: 10px 12px;
    border: 1px solid var(--admin-border);
    border-radius: 4px;
    cursor: pointer;
}

.admin-shipping-page .admin-checkbox-row:hover {
    border-color: var(--admin-muted);
}

.admin-shipping-page .admin-checkbox-row input[type="checkbox"] {
    position: static;
    flex: 0 0 auto;
    margin: 3px 0 0;
}

.admin-shipping-page #shipping-categories {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
    margin-bottom: 22px;
}

.admin-shipping-page #shipping-categories > h3 {
    grid-column: 1 / -1;
}

.admin-shipping-page .admin-shipping-inactive-note {
    padding: 10px 12px;
    color: var(--admin-red);
    background: var(--admin-bg);
    border-left: 4px solid var(--admin-red);
}

.admin-shipping-page [data-shipping-rate-panel].has-preserved-value,
.admin-shipping-page [data-shipping-band-panel].has-preserved-value,
.admin-shipping-page [data-shipping-carrier-custom].has-preserved-value {
    padding: 14px;
    background: var(--admin-bg);
    border: 1px solid var(--admin-border);
    border-radius: 4px;
}

.admin-shipping-page .admin-shipping-band-editor {
    margin-bottom: 12px;
    padding: 16px;
    background: var(--admin-bg);
    border: 1px solid var(--admin-border);
    border-radius: 8px;
}

.admin-shipping-page .admin-shipping-band-heading {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 14px;
}

.admin-shipping-page .admin-shipping-band-heading > div {
    min-width: 0;
}

.admin-shipping-page .admin-shipping-band-rows {
    display: grid;
    gap: 10px;
}

.admin-shipping-page .admin-shipping-band-row {
    display: grid;
    grid-template-columns: 64px repeat(3, minmax(90px, 1fr)) auto;
    align-items: end;
    gap: 10px;
    padding: 12px;
    border: 1px solid var(--admin-border);
    border-radius: 4px;
}

.admin-shipping-page .admin-shipping-band-row > strong {
    align-self: center;
    color: var(--admin-navy);
}

.admin-shipping-page .admin-shipping-band-field {
    min-width: 0;
    margin: 0;
}

#page-inner .admin-shipping-page .admin-shipping-band-field .form-control {
    margin-top: 5px;
}

.admin-shipping-page .admin-shipping-band-count {
    margin: 10px 0 0;
}

.admin-shipping-page .admin-shipping-band-feedback:empty {
    display: none;
}

.admin-shipping-page .admin-shipping-band-source {
    margin: 0;
    border: 1px solid var(--admin-border);
    border-radius: 4px;
}

.admin-shipping-page .admin-shipping-band-source summary {
    min-height: 44px;
    padding: 10px 12px;
    color: var(--admin-navy);
    cursor: pointer;
}

.admin-shipping-page .admin-shipping-band-source[open] summary {
    border-bottom: 1px solid var(--admin-border);
}

.admin-shipping-page .admin-shipping-band-source-body {
    padding: 14px;
}

.admin-shipping-page .admin-shipping-country-tools {
    margin-bottom: 12px;
}

#page-inner .admin-shipping-page .admin-shipping-country-tools .form-control {
    max-width: 520px;
}

.admin-shipping-page .admin-shipping-selection-summary {
    display: grid;
    gap: 3px;
    max-width: 520px;
    margin-top: 10px;
    padding: 12px;
    background: var(--admin-bg);
    border: 1px solid var(--admin-border);
    border-radius: 4px;
}

.admin-shipping-page .admin-shipping-country-list {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 8px;
    max-height: 380px;
    padding: 10px;
    overflow-y: auto;
    background: var(--admin-bg);
    border: 1px solid var(--admin-border);
    border-radius: 4px;
    scrollbar-gutter: stable;
}

.admin-shipping-page .admin-row-actions {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 10px;
}

.admin-shipping-page .admin-empty-state {
    padding: 24px;
    color: var(--admin-muted);
    text-align: center;
    border: 1px solid var(--admin-border);
    border-radius: 8px;
}

#page-inner .admin-shipping-page .table-responsive {
    width: 100%;
    max-width: 100%;
    margin-bottom: 18px;
    overflow-x: auto;
    border: 1px solid var(--admin-border);
    border-radius: 8px;
    -webkit-overflow-scrolling: touch;
}

#page-inner .admin-shipping-page table.table {
    min-width: 760px;
    margin: 0;
}

.admin-shipping-page caption {
    padding: 10px 14px;
    text-align: left;
}

@media (max-width: 900px) {
    .admin-shipping-page .admin-shipping-country-list {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .admin-shipping-page .admin-shipping-band-row {
        grid-template-columns: 54px repeat(3, minmax(80px, 1fr));
    }

    .admin-shipping-page .admin-shipping-band-remove {
        grid-column: 2 / -1;
        justify-self: start;
    }
}

@media (max-width: 767px) {
    .admin-shipping-page .admin-operation-panel,
    .admin-shipping-page .admin-empty-state,
    #page-inner .admin-shipping-page fieldset.admin-form-section,
    .admin-shipping-page section.admin-form-section {
        padding: 16px;
    }

    .admin-shipping-page #shipping-categories,
    .admin-shipping-page .admin-shipping-country-list {
        grid-template-columns: minmax(0, 1fr);
    }

    .admin-shipping-page .admin-shipping-country-list {
        max-height: 340px;
    }

    .admin-shipping-page .admin-shipping-band-heading {
        display: block;
    }

    .admin-shipping-page .admin-shipping-band-heading .btn {
        width: 100%;
        margin-top: 10px;
    }

    .admin-shipping-page .admin-shipping-band-row {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .admin-shipping-page .admin-shipping-band-row > strong,
    .admin-shipping-page .admin-shipping-band-field:last-of-type,
    .admin-shipping-page .admin-shipping-band-remove {
        grid-column: 1 / -1;
    }

    .admin-shipping-page .admin-shipping-band-remove {
        width: 100%;
    }
}

@media (max-width: 420px) {
    .admin-shipping-page .dashboard-header > .btn,
    .admin-shipping-page .admin-row-actions > .btn,
    .admin-shipping-page .admin-row-actions > a {
        width: 100%;
    }

    .admin-shipping-page .admin-shipping-band-row {
        grid-template-columns: minmax(0, 1fr);
    }

    .admin-shipping-page .admin-shipping-band-field,
    .admin-shipping-page .admin-shipping-band-field:last-of-type {
        grid-column: 1;
    }
}

@media (prefers-reduced-motion: reduce) {
    .admin-shipping-page * {
        animation: none !important;
        scroll-behavior: auto !important;
        transition: none !important;
    }
}

