/* Modern administration shell */
:root { --admin-red:#d92331; --admin-navy:#1d2230; --admin-sidebar:#202431; --admin-bg:#f4f6f9; --admin-border:#e5e8ee; --admin-muted:#717786; }
body { color:#252936; background:var(--admin-bg); }
#wrapper { min-height:100vh; background:var(--admin-sidebar); }
.navbar-cls-top { display:block!important; min-height:72px; background:#fff; border:0; box-shadow:0 2px 14px rgba(26,31,44,.08); }
.navbar-header { width:240px; height:72px; padding:0; display:flex; align-items:center; justify-content:center; background:var(--admin-navy); }
.admin-brand { display:flex; align-items:center; justify-content:center; width:100%; height:100%; padding:13px 22px; }
.admin-brand img { display:block; max-width:190px; max-height:46px; }
.admin-top-actions { height:72px; display:flex; align-items:center; justify-content:flex-end; gap:9px; padding:0 28px; }
.admin-top-actions a,.admin-welcome { display:inline-flex; align-items:center; gap:7px; padding:9px 12px; color:#5b6170; font-size:13px; border-radius:7px; }
.admin-top-actions a:hover { color:var(--admin-red); background:#f7f8fa; text-decoration:none; }
.admin-top-actions .admin-logout { color:#fff; background:var(--admin-red); }
.admin-top-actions .admin-logout:hover { color:#fff; background:#b91c28; }
.navbar-side { width:240px; min-height:calc(100vh - 72px); background:var(--admin-sidebar); }
.admin-nav-label { padding:25px 20px 13px!important; color:#fff; border:0!important; }
.admin-nav-label span,.admin-nav-label small { display:block; }
.admin-nav-label span { font-size:12px; font-weight:700; letter-spacing:1.2px; text-transform:uppercase; }
.admin-nav-label small { margin-top:3px; color:#7f879a; font-size:11px; }
.sidebar-collapse .nav > li > a { color:#abb1bf; background:transparent; font-size:13px; border-left:3px solid transparent; }
.sidebar-collapse > .nav > li > a { padding:13px 17px; }
.sidebar-collapse > .nav > li { border-color:rgba(255,255,255,.05); }
.sidebar-collapse .nav > li > a:hover,.sidebar-collapse .nav > li > a:focus,.sidebar-collapse .nav > li > a.active-menu { color:#fff!important; background:rgba(217,35,49,.15)!important; border-left-color:var(--admin-red); }
.sidebar-collapse .nav > li > a i { width:21px; margin-right:10px; color:#858d9f; font-size:16px!important; text-align:center; }
.sidebar-collapse .nav > li > a:hover i,.sidebar-collapse .nav > li > a.active-menu i { color:#fff; }
.nav-second-level li a { padding:10px 15px 10px 48px; color:#959cad!important; font-size:12px; }
.nav-third-level li a { padding-left:62px; }
.nav-second-level > li > a:before,.nav-third-level > li > a:before,.nav-second-level > li > a:after,.nav-third-level > li > a:after { display:none; }
#page-wrapper { min-height:calc(100vh - 72px); background:var(--admin-bg); }
#page-inner { width:auto; min-height:calc(100vh - 108px); margin:0; padding:28px 30px 45px; background:transparent!important; }
#page-inner > hr:first-of-type { display:none; }
#page-inner h2 { color:#202533; }
.dashboard-header { display:flex; align-items:flex-start; justify-content:space-between; gap:24px; margin-bottom:28px; }
.dashboard-eyebrow { color:var(--admin-red); font-size:11px; font-weight:700; letter-spacing:1.4px; text-transform:uppercase; }
.dashboard-header h1 { margin:4px 0 7px; color:#1d2230; font-size:30px; font-weight:700; }
.dashboard-header p,.dashboard-section-title p { margin:0; padding:0; color:var(--admin-muted); font-size:13px; line-height:1.55; }
.dashboard-date { padding:10px 14px; color:#5c6270; background:#fff; border:1px solid var(--admin-border); border-radius:9px; box-shadow:0 3px 10px rgba(29,34,48,.04); font-size:12px; white-space:nowrap; }
.dashboard-date i { margin-right:7px; color:var(--admin-red); }
.dashboard-section-title { display:flex; align-items:end; justify-content:space-between; margin-bottom:15px; }
.dashboard-section-title h2 { margin:0 0 4px!important; font-size:18px!important; font-weight:700; }
.dashboard-card-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:16px; }
.dashboard-card { position:relative; min-height:118px; display:flex; align-items:center; gap:16px; padding:22px; overflow:hidden; color:#252936; background:#fff; border:1px solid var(--admin-border); border-radius:13px; box-shadow:0 5px 18px rgba(29,34,48,.05); transition:transform .18s,box-shadow .18s,border-color .18s; }
.dashboard-card:hover { color:#252936; text-decoration:none; transform:translateY(-3px); box-shadow:0 12px 27px rgba(29,34,48,.1); border-color:#d9dde5; }
