.dashboard-card-arrow { position:absolute; right:17px; color:#c3c7d0; }
.dashboard-card-blue .dashboard-card-icon{color:#2876d1;background:#eaf3ff}.dashboard-card-red .dashboard-card-icon{color:#d92331;background:#ffedef}.dashboard-card-gold .dashboard-card-icon{color:#b77909;background:#fff5d9}.dashboard-card-purple .dashboard-card-icon{color:#7652c7;background:#f1ecff}.dashboard-card-green .dashboard-card-icon{color:#22865d;background:#e7f8f0}.dashboard-card-pink .dashboard-card-icon{color:#c4407f;background:#fdebf4}
.dashboard-quick-section { margin-top:30px; }
