.dashboard-quick-grid > a:hover { color:var(--admin-red); border-color:#f0b7bc; text-decoration:none; }
.dashboard-quick-grid > a > i { width:36px; height:36px; display:grid; place-items:center; color:#fff; background:var(--admin-navy); border-radius:9px; font-size:16px; }
.dashboard-quick-grid strong,.dashboard-quick-grid small { display:block; }
.dashboard-quick-grid strong { font-size:13px; }.dashboard-quick-grid small { margin-top:3px; color:#8a8f9c; font-size:10px; }
.panel { border-color:var(--admin-border); border-radius:10px; box-shadow:0 4px 15px rgba(29,34,48,.05); }
.panel-default > .panel-heading { padding:14px 17px; color:#262b38; background:#fff; border-color:var(--admin-border); border-radius:10px 10px 0 0; font-weight:700; }
.table { background:#fff; }.table > thead > tr > th { color:#505665; background:#f8f9fb; border-color:var(--admin-border); font-size:12px; }
.btn { border-radius:7px; }.btn-primary { background:var(--admin-red); border-color:var(--admin-red); }
