.dashboard-activity-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(280px,.85fr);gap:17px;margin-top:30px}.dashboard-activity-card,.dashboard-system-card{overflow:hidden;background:#fff;border:1px solid var(--admin-border);border-radius:14px;box-shadow:0 6px 20px rgba(29,34,48,.05)}.dashboard-activity-heading{min-height:73px;display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid #edf0f4}.dashboard-activity-heading h2{margin:0 0 3px!important;color:#262b38!important;font-size:16px!important;font-weight:700}.dashboard-activity-heading p{margin:0;padding:0;color:#9196a1;font-size:10px}.dashboard-activity-heading>a{color:var(--admin-red);font-size:11px;font-weight:700}.dashboard-activity-heading>a:hover{text-decoration:none}.dashboard-order-row{min-height:67px;display:grid;grid-template-columns:38px minmax(100px,1fr) 70px 80px;align-items:center;gap:11px;padding:10px 20px;color:#353a47;border-bottom:1px solid #f0f2f5}.dashboard-order-row:last-child{border-bottom:0}.dashboard-order-row:hover{color:#353a47;background:#fafbfc;text-decoration:none}.dashboard-order-avatar{width:34px;height:34px;display:grid;place-items:center;color:#596174;background:#f0f2f6;border-radius:9px}.dashboard-order-info strong,.dashboard-order-info small{display:block}.dashboard-order-info strong{font-size:12px}.dashboard-order-info small{margin-top:3px;color:#9ba0aa;font-size:9px}.dashboard-order-status{justify-self:start;padding:4px 8px;border-radius:20px;font-size:9px;font-weight:700}.dashboard-order-status.is-paid{color:#176542;background:#def5e9}.dashboard-order-status.is-pending{color:#8a620d;background:#fff1c9}.dashboard-order-total{text-align:right;font-size:12px}.dashboard-no-activity{padding:35px;color:#9298a5;text-align:center}.dashboard-system-list>div{min-height:64px;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 20px;border-bottom:1px solid #f0f2f5}.dashboard-system-list>div:last-child{border-bottom:0}.dashboard-system-list span{display:flex;align-items:center;gap:9px;color:#565d6c;font-size:11px}.dashboard-system-list span>i{width:27px;height:27px;display:grid;place-items:center;color:#747b8b;background:#f1f3f6;border-radius:7px}.dashboard-system-list strong{color:#333946;font-size:10px}.dashboard-system-list .system-online{color:#23805a}.system-online>i{display:inline-block;width:7px;height:7px;margin-right:5px;background:#31b477;border-radius:50%;box-shadow:0 0 0 3px #ddf5ea}
