"""Shared state-building helpers for graph orchestration tests."""

from __future__ import annotations

from typing import cast

from langgraph.types import Command

from src.autopilot.contracts.base_state import OrchestrationState


def _os(d: dict[str, object]) -> OrchestrationState:
    """Narrow a dict to OrchestrationState for pyright compatibility."""
    return cast(OrchestrationState, {"messages": [], **d})


def _update(result: object) -> dict[str, object]:
    """Narrow Command.update (typed Any|None in stub) to dict."""
    assert isinstance(result, Command)
    assert isinstance(result.update, dict)
    return cast(dict[str, object], result.update)

"""Screen pushes and timeline rendering for the TUI event consumer.

Every helper here is a pure presentation boundary: it reads the current
projection store and pushes it into widgets. Records (timeline entries)
are appended in arrival order; expensive Run-screen repaints are driven
by :func:`push_run_projection`, which the consumer calls only when a
slice's revision counter moved.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, cast

from textual.css.query import NoMatches, TooManyMatches
from textual.notifications import SeverityLevel

import src.key_catalog
from src.logging import get_logger
from src.tui.nav import SCREEN_REVIEW, SCREEN_SUBMIT_PREVIEW, switch_screen_by_name
from src.tui.projections import Dirty
from src.tui.projections.submit_preview import refresh_submit_preview
from src.tui.screens.trace import (
    apply_trace_document_evidence,
    apply_trace_llm_summaries,
)
from src.tui.styles import COLOR_MUTED_DIM
from src.tui.widgets.run.diagnostics import DiagnosticsLog

from .routing import screen_action_for_event

if TYPE_CHECKING:
    from collections.abc import Callable, Sequence
    from typing import Protocol

    from textual.app import App

    from src.agui import BaseEvent
    from src.tui.events.consumer import EventContext
    from src.tui.projections import models
    from src.tui.screens.run import RunScreen

logger = get_logger(__name__)

_TIMELINE_ID: str = "#timeline"

_NOTIFY_REVIEW_KEY: str = "v"
_NOTIFY_SUBMIT_KEY: str = src.key_catalog.FRAG_P
_NOTIFY_REVIEW_MESSAGE: str = f"Review queue ready — press {_NOTIFY_REVIEW_KEY} to open"
_NOTIFY_SUBMIT_MESSAGE: str = (
    f"Submit Preview ready — press {_NOTIFY_SUBMIT_KEY} to open"
)
_NOTIFY_SEVERITY: SeverityLevel = "information"


class _GraphOperationApplier(Protocol):
    def apply_graph_operations(
        self, records: Sequence[models.GraphOperationRecord]
    ) -> None: ...


def write_timeline(
    run_screen: RunScreen, message: str, color: str = COLOR_MUTED_DIM
) -> None:
    """Echo ``message`` to the run timeline if the screen is attached.

    Shared helper so event-processing and mutation-dispatch error
    surfacing flows through a single code path (keeps vibeforcer's
    repeated-code-block detector happy).
    """
    if not run_screen.is_attached:
        return
    try:
        timeline = run_screen.query_one(_TIMELINE_ID, DiagnosticsLog)
    except (NoMatches, TooManyMatches):
        return
    timeline.write_status(message, color)


def render_timeline_message(entry: models.TimelineEntry | None) -> str:
    """Return the message for a freshly-appended ``TimelineEntry``.

    Returns ``""`` when ``apply`` did not append (silenced handler,
    duplicate collapse, or fragment-cleaned-to-empty).
    """
    return entry.message if entry is not None else ""


def append_timeline_record(
    run_screen: RunScreen,
    event: BaseEvent,
    entry: models.TimelineEntry | None,
) -> None:
    """Append one reduced timeline record in arrival order.

    Called for every event so diagnostic history stays complete and
    ordered even though Run-screen repaints are coalesced per frame.
    """
    if not run_screen.is_attached:
        return
    _write_timeline_event(run_screen, event, entry)


def render_run(
    run_screen: RunScreen,
    event: BaseEvent,
    projection: models.RunProjection,
    entry: models.TimelineEntry | None,
) -> None:
    if not run_screen.is_attached:
        return
    run_screen.apply_projection(projection)
    _write_timeline_event(run_screen, event, entry)


def push_run_projection(ctx: EventContext) -> None:
    """Publish the latest run projection to the attached Run screen."""
    if not ctx.run_screen.is_attached:
        return
    logger.debug("tui.run_projection_pushed", stage=ctx.store.run.stage)
    ctx.run_screen.apply_projection(ctx.store.run)


def _write_timeline_event(
    run_screen: RunScreen,
    event: BaseEvent,
    entry: models.TimelineEntry | None,
) -> None:
    message = render_timeline_message(entry)
    if not message:
        return
    ts = event.timestamp or ""
    try:
        timeline = run_screen.query_one(_TIMELINE_ID, DiagnosticsLog)
    except (NoMatches, TooManyMatches):
        return
    timeline.write_event(event, message, ts)


def refresh_secondary_screens(ctx: EventContext, dirty: Dirty) -> None:
    """Push dirty projection slices into their secondary screens."""
    if Dirty.TOOL_ACTIVITY in dirty:
        _safe_apply(lambda: ctx.run_screen.apply_tool_activity(ctx.store.agent_trace))
    if Dirty.GRAPH_OPERATIONS in dirty:
        _safe_apply(lambda: _apply_graph_operations(ctx))
    if Dirty.FIELDS in dirty:
        _safe_apply(
            lambda: ctx.trace_screen.apply_fields(ctx.store.fields, run=ctx.store.run)
        )
    if Dirty.LLM_SUMMARIES in dirty:
        _safe_apply(
            lambda: apply_trace_llm_summaries(
                ctx.trace_screen, ctx.store.llm_summaries
            ),
        )
    if Dirty.REVIEW in dirty:
        _safe_apply(lambda: ctx.review_screen.apply_review(ctx.store.review))
    if Dirty.HEALTH in dirty:
        _safe_apply(lambda: ctx.health_screen.apply_health(ctx.store.health))
    if Dirty.SUBMIT_PREVIEW in dirty:
        _safe_apply(
            lambda: ctx.submit_preview_screen.apply_preview(ctx.store.submit_preview)
        )
        _safe_apply(
            lambda: apply_trace_document_evidence(
                ctx.trace_screen,
                ctx.store.submit_preview.document_evidence,
            )
        )
    if Dirty.AGENT_TRACE in dirty:
        _safe_apply(lambda: _apply_agent_trace(ctx))
    if Dirty.BROWSER_SESSION in dirty:
        _safe_apply(
            lambda: ctx.run_screen.apply_browser_session(ctx.store.browser_session)
        )
        _safe_apply(
            lambda: ctx.review_screen.apply_browser_session(ctx.store.browser_session)
        )
        _safe_apply(
            lambda: ctx.submit_preview_screen.apply_browser_session(
                ctx.store.browser_session
            )
        )


def maybe_show_terminal_screen(ctx: EventContext, event: BaseEvent) -> None:
    """Route ``event`` to its terminal screen, or notify when Run is hidden."""
    action = screen_action_for_event(
        ctx.store,
        event,
        ctx.controller,
        run_screen_attached=ctx.run_screen.is_attached,
    )
    if action is None:
        return
    if action.target == SCREEN_SUBMIT_PREVIEW:
        refresh_submit_preview(ctx.store)
        ctx.submit_preview_screen.apply_preview(ctx.store.submit_preview)
    if isinstance(action, ScreenSwitch):
        try:
            switch_screen_by_name(ctx.run_screen, action.target)
        except RuntimeError:
            logger.warning("Screen switch failed during event routing", exc_info=True)
            return
    else:
        _notify_terminal_target(ctx, action.target)


def _apply_graph_operations(ctx: EventContext) -> None:
    """Forward graph operations to the run screen when it is attached."""
    if not ctx.run_screen.is_attached:
        return
    screen = cast("_GraphOperationApplier", ctx.run_screen)
    _safe_apply(lambda: screen.apply_graph_operations(ctx.store.graph_operations))


def _apply_agent_trace(ctx: EventContext) -> None:
    """Forward agent trace to the run screen via the render helper."""
    if not ctx.run_screen.is_attached:
        return
    from src.tui.screens.run.render import apply_agent_trace

    apply_agent_trace(ctx.run_screen, ctx.store.agent_trace)


def _notify_terminal_target(ctx: EventContext, target: str) -> None:
    """Surface a banner pointing at ``target`` without switching screens.

    Used when the operator has navigated away from Run (e.g. to Trace or
    Health) so a terminal/HITL milestone doesn't yank focus mid-task.
    """
    if target == SCREEN_REVIEW:
        message = _NOTIFY_REVIEW_MESSAGE
    elif target == SCREEN_SUBMIT_PREVIEW:
        message = _NOTIFY_SUBMIT_MESSAGE
    else:
        return
    logger.info("tui.terminal_target_notified", target=target)
    cast("App[object]", ctx.run_screen.app).notify(message, severity=_NOTIFY_SEVERITY)


def _safe_apply(update: Callable[[], None]) -> None:
    try:
        update()
    except NoMatches:
        logger.debug("_safe_apply: widget not found for screen push")
    except TooManyMatches:
        logger.debug("_safe_apply: unexpected duplicate widget for screen push")


__all__ = [
    "append_timeline_record",
    "maybe_show_terminal_screen",
    "push_run_projection",
    "refresh_secondary_screens",
    "render_run",
    "render_timeline_message",
    "write_timeline",
]

from typing import Any

def identity(value: Any) -> Any:
    return value

"""Minimal TOML serializer for slopgate repo config files.

Handles the shapes that appear in ``slopgate.toml``: scalar keys, string
arrays, top-level tables, and the nested ``rule_surfaces."<id>"`` tables with
inline ``hook``/``cli`` maps. Values that cannot round-trip raise
:class:`ValueError` rather than silently corrupting the file.
"""

from __future__ import annotations

import json
from collections.abc import Mapping

_INLINE_TABLE_SECTIONS = frozenset({"rule_surfaces"})


def _scalar(value: object) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, str):
        return json.dumps(value, ensure_ascii=False)
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return str(value)
    if isinstance(value, list):
        return "[" + ", ".join(_scalar(item) for item in value) + "]"
    raise ValueError(f"unsupported TOML value: {value!r}")


def _inline_table(value: Mapping[str, object]) -> str:
    parts = []
    for key, item in value.items():
        if isinstance(item, Mapping):
            raise ValueError(f"nested table inside inline table: {key!r}")
        parts.append(f"{_quote_key(key)} = {_scalar(item)}")
    return "{ " + ", ".join(parts) + " }"


def _quote_key(key: str) -> str:
    if key.isalnum() and not key[0].isdigit():
        return key
    return json.dumps(key)


def _write_table(lines: list[str], table: Mapping[str, object]) -> None:
    for key, value in table.items():
        if isinstance(value, Mapping):
            raise ValueError(f"unexpected nested table {key!r} at top level")
        lines.append(f"{_quote_key(key)} = {_scalar(value)}")


def dumps(data: Mapping[str, object]) -> str:
    """Serialize a parsed TOML dict back to TOML text."""
    lines: list[str] = []
    for key, value in data.items():
        if isinstance(value, Mapping):
            if key in _INLINE_TABLE_SECTIONS:
                for rule_id, surface in value.items():
                    lines.append(f"[{key}.{_quote_key(str(rule_id))}]")
                    if isinstance(surface, Mapping):
                        for surface_key, surface_value in surface.items():
                            if isinstance(surface_value, Mapping):
                                lines.append(
                                    f"{surface_key} = {_inline_table(surface_value)}"
                                )
                            else:
                                lines.append(
                                    f"{surface_key} = {_scalar(surface_value)}"
                                )
                    lines.append("")
                continue
            lines.append(f"[{key}]")
            _write_table(lines, value)
            lines.append("")
            continue
        lines.append(f"{_quote_key(key)} = {_scalar(value)}")
    text = "\n".join(lines)
    if text.endswith("\n\n"):
        text = text.rstrip("\n") + "\n"
    return text if text.endswith("\n") else text + "\n"

from orders.bus import EventBus

def publish_order_created(bus: EventBus, order_id: str) -> None:
    event = {"order_id": order_id}
    bus.publish("order.created", event)

