from typing import Any

def identity(value: Any) -> Any:
    return value

"""Final submit-click executor — runs only after operator authorization.

Uses the approved submit context from the authorization gate. The approved
selector and page signature are verified before click; if the page changed or
the context is missing, the node aborts without clicking.
"""

from __future__ import annotations

import re
from typing import Final, Literal, cast

from langgraph.types import Command
from playwright import async_api

from src.autopilot.contracts.base_state import OrchestrationState
from src.autopilot.tools.browser import get_required_page
from src.browser_runtime.page_ops.validity import page_signature
from src.key_catalog import (
    DETAILS,
    JVK_CONCERNS,
    JVK_OVERALL_VERDICT,
    JVK_SUMMARY,
    PK_BLOCKER_TYPE,
    PK_CONTROL_ID,
    PK_MESSAGE,
    PK_REASON,
    PK_TYPE,
    SELECTOR,
    VD_BLOCK,
)
from src.logging import get_logger
from src.types.typed import JsonObject, as_str

from ._approval_context import (
    SUBMIT_CONTEXT_SELECTOR,
    SubmitApprovalContext,
    submit_state_signature,
)
from ._selectors import SubmitLocatorPolicy, find_unique_submit_selector

_CLICK_TIMEOUT_MS: Final[int] = 15_000
_POST_CLICK_NETWORK_IDLE_MS: Final[int] = 30_000
_SUBMIT_CLICK_BLOCKER_TYPE: Final[str] = "submit_click_failure"
_CONFIRMATION_TEXT_RE: Final[re.Pattern[str]] = re.compile(
    r"(thank you|submitted|application received|success)", re.I
)
_VALIDATION_ERROR_SELECTOR: Final[str] = (
    "[aria-invalid='true'], [role='alert'], .error, .field-error, .validation-error"
)

logger = get_logger(__name__)
type _ClickGoto = Literal["__end__", "blocker_state"]


def _approved_context_from_state(
    state: OrchestrationState,
) -> JsonObject | None:
    """Return the approved submit context payload from graph state, if present."""
    approved = state.get("approved_submit_context")
    if isinstance(approved, dict):
        return approved
    return None


async def _current_submit_context(
    state: OrchestrationState,
) -> SubmitApprovalContext | None:
    """Build the current submit approval context from the live page and state."""
    page = get_required_page()
    selector = await find_unique_submit_selector(page, SubmitLocatorPolicy.default())
    if selector is None:
        return None
    page_signature_value = await page_signature(page)
    return SubmitApprovalContext(
        page_signature=f"page={page_signature_value}|selector={selector}",
        selector=selector,
        state_signature=submit_state_signature(state),
    )


async def _approved_context_is_fresh(
    approved: JsonObject,
    state: OrchestrationState,
) -> bool:
    """Return True when the live page/state still matches the approved context."""
    current = await _current_submit_context(state)
    if current is None:
        return False
    current_payload = current.to_payload(
        control_id=as_str(approved.get(PK_CONTROL_ID), ""),
        interrupt_type=as_str(approved.get(PK_TYPE), ""),
    )
    return current_payload == approved


def _selector_from_approved_context(approved: JsonObject) -> str | None:
    """Return the approved selector string from the persisted context."""
    selector = approved.get(SUBMIT_CONTEXT_SELECTOR)
    if isinstance(selector, str) and selector:
        return selector
    return None


def _submit_click_blocker(
    reason: str,
    message: str,
) -> Command[Literal["blocker_state"]]:
    """Build a blocker-state command for a pre-click submit failure."""
    return cast(
        "Command[Literal['blocker_state']]",
        Command(
            update={
                "judge_result": {
                    JVK_OVERALL_VERDICT: VD_BLOCK,
                    JVK_SUMMARY: message,
                    JVK_CONCERNS: [
                        {
                            PK_CONTROL_ID: "submit_authorization",
                            PK_BLOCKER_TYPE: _SUBMIT_CLICK_BLOCKER_TYPE,
                            PK_MESSAGE: message,
                            PK_REASON: reason,
                            "submit_click_failed": True,
                        }
                    ],
                },
            },
            goto="blocker_state",
        ),
    )


def _check_approved_context(
    approved: JsonObject | None,
    is_fresh: bool,
    selector: str | None,
) -> None:
    """Validate the approved submit context. Raises on failure via blocker return.

    The caller must catch the returned blocker command via an explicit
    ``Command[Literal["blocker_state"]]`` check; this function signals
    failure by raising a private sentinel that the orchestrator catches.
    """
    if approved is None:
        logger.error("submit_click missing approved_submit_context in state; aborting")
        raise _PreClickFailure(
            "missing_approved_context",
            "Operator approved submission but the approved context is missing from state.",
        )
    if not is_fresh:
        logger.warning("submit_click approved context stale; aborting without click")
        raise _PreClickFailure(
            "stale_approved_context",
            "The submit page changed after operator approval; re-approval required.",
        )
    if selector is None:
        logger.error("submit_click approved context missing selector; aborting")
        raise _PreClickFailure(
            "missing_approved_selector",
            "The approved submit selector is missing from the persisted context.",
        )


class _PreClickFailure(Exception):
    """Raised when submit-click pre-conditions fail; must be caught and routed
    to ``blocker_state``."""

    def __init__(self, reason: str, message: str) -> None:
        super().__init__(message)
        self.reason = reason


async def _click_and_wait_for_submit(
    selector: str,
) -> None:
    """Click the submit button and wait for network idle.

    Raises ``_PreClickFailure`` when the click itself fails.
    Post-click network-idle timeouts are logged and tolerated.
    """
    page = get_required_page()
    before_url = page.url
    logger.info("submit_click invoking page.click", selector=selector)
    try:
        await page.click(selector, timeout=_CLICK_TIMEOUT_MS)
    except (async_api.TimeoutError, async_api.Error) as err:
        logger.error(
            "submit_click failed during page.click",
            selector=selector,
            error_type=type(err).__name__,
            error=str(err),
        )
        raise _PreClickFailure(
            "click_timeout",
            "Submit click timed out or failed; the application may not have been submitted.",
        ) from err

    try:
        await page.wait_for_load_state(
            "networkidle", timeout=_POST_CLICK_NETWORK_IDLE_MS
        )
    except (async_api.TimeoutError, async_api.Error) as err:
        logger.warning(
            "submit_click post-submit networkidle wait did not settle",
            error_type=type(err).__name__,
        )

    if not await _submission_confirmed(page, selector, before_url):
        raise _PreClickFailure(
            "submit_unconfirmed",
            "Submit click did not produce a confirmation signal; review the page before continuing.",
        )


async def _submission_confirmed(
    page: async_api.Page,
    selector: str,
    before_url: str,
) -> bool:
    if page.url != before_url:
        return True
    if await _has_confirmation_text(page):
        return True
    if await _has_validation_errors(page):
        return False
    return not await _has_enabled_submit_button(page, selector)


async def _has_confirmation_text(page: async_api.Page) -> bool:
    try:
        return await page.get_by_text(_CONFIRMATION_TEXT_RE).first.is_visible(
            timeout=1000
        )
    except (async_api.TimeoutError, async_api.Error, AttributeError, TypeError):
        return False


async def _has_validation_errors(page: async_api.Page) -> bool:
    try:
        return await page.locator(_VALIDATION_ERROR_SELECTOR).count() > 0
    except (async_api.Error, AttributeError, TypeError):
        return False


async def _has_enabled_submit_button(page: async_api.Page, selector: str) -> bool:
    try:
        locator = page.locator(selector)
        count = min(await locator.count(), 5)
        for index in range(count):
            if not await locator.nth(index).is_disabled():
                return True
    except (async_api.Error, AttributeError, TypeError):
        return False
    return False


async def node_submit_click(
    state: OrchestrationState,
) -> Command[_ClickGoto]:
    """Click the form's submit button using the operator-approved context.

    Pre-click failures route to ``blocker_state`` to prevent a false
    RUN_FINISHED outcome.  Only a confirmed click reaches ``__end__``.
    """
    approved = _approved_context_from_state(state)
    is_fresh = await _approved_context_is_fresh(approved or {}, state)
    selector = _selector_from_approved_context(approved) if approved else None

    try:
        _check_approved_context(approved, is_fresh, selector)
        await _click_and_wait_for_submit(cast(str, selector))
    except _PreClickFailure as failure:
        return cast(
            "Command[_ClickGoto]",
            _submit_click_blocker(failure.reason, str(failure)),
        )

    logger.info("submit_click completed", selector=selector)
    return cast(
        "Command[_ClickGoto]",
        Command(
            update={
                "status_updates": [
                    {
                        "stage": "submit_confirmed",
                        "message": "Application submission confirmed.",
                        DETAILS: {SELECTOR: selector},
                    }
                ]
            },
            goto="__end__",
        ),
    )


__all__ = [
    "node_submit_click",
]

import { useState } from "react";

interface CommandStats {
	command: string;
	total: number;
	pass: number;
	fail: number;
	medianRuntime: number;
	failures: string[];
}

interface Props {
	passCount: number;
	failCount: number;
	byCommand: CommandStats[];
}

const RUNTIME_BAR_MAX_WIDTH_PERCENT = 100;
const PASS_COLOR = "hsl(var(--signal-allow))";
const FAIL_COLOR = "hsl(var(--signal-deny))";

function failureRate(command: CommandStats): number {
	return command.total > 0 ? command.fail / command.total : 0;
}

export function AsyncJobs({ passCount, failCount, byCommand }: Props) {
	const [expandedCmd, setExpandedCmd] = useState<string | null>(null);

	const totalJobs = passCount + failCount;
	const hasJobs = totalJobs > 0;
	const passPercent = hasJobs ? Math.round((passCount / totalJobs) * 100) : 0;
	const passFailBackground = hasJobs
		? `conic-gradient(${PASS_COLOR} 0 ${passPercent}%, ${FAIL_COLOR} ${passPercent}% 100%)`
		: "conic-gradient(hsl(var(--border)) 0 100%)";
	const passFailTitle = hasJobs
		? `${passCount} passed, ${failCount} failed`
		: "No async jobs ran in this window";
	const passFailLabel = hasJobs ? `${passPercent}%` : "idle";

	const runtimeData = [...byCommand]
		.sort((a, b) => b.medianRuntime - a.medianRuntime)
		.slice(0, 8)
		.map((c) => ({
			command: c.command,
			displayCommand: c.command.length > 20 ? `${c.command.slice(0, 18)}…` : c.command,
			runtime: Math.round(c.medianRuntime),
		}));
	const maxRuntime = Math.max(...runtimeData.map((row) => row.runtime), 1);

	const noisy = [...byCommand]
		.filter((c) => c.fail > 0)
		.sort((a, b) => failureRate(b) - failureRate(a))
		.slice(0, 5);

	return (
		<div className="space-y-4">
			<h3 className="text-xs text-muted-foreground uppercase tracking-wider px-1">
				Async quality checks
			</h3>

			{!hasJobs ? (
				<div className="border border-border rounded-md bg-card/30 p-8 flex flex-col items-center justify-center text-center gap-2">
					<span className="text-xs font-semibold text-foreground">No async jobs ran in this window</span>
					<span className="text-[11px] text-muted-foreground/80 max-w-xs">
						Trace logs show no background verification or linter check invocations.
					</span>
				</div>
			) : (
				<>
					<div className="grid grid-cols-2 gap-3">
						{/* Pass / Fail */}
						<div className="border border-border rounded-md bg-card/30 p-3">
							<h4 className="text-[11px] text-muted-foreground uppercase mb-2 text-center font-semibold tracking-wider">
								Pass / Fail
							</h4>
							<div className="h-[150px]">
								<div className="flex h-full items-center justify-center gap-4">
									<div
										aria-label={passFailTitle}
										className="grid h-24 w-24 place-items-center rounded-full shadow-inner"
										role="img"
										style={{
											background: passFailBackground,
										}}
										title={passFailTitle}
									>
										<div className="grid h-14 w-14 place-items-center rounded-full bg-card text-center">
											<span className="font-mono text-sm font-semibold text-muted-foreground/80">
												{passFailLabel}
											</span>
										</div>
									</div>
									<div className="space-y-2 text-xs text-muted-foreground font-medium">
										<LegendItem color={PASS_COLOR} label="Pass" value={passCount} />
										<LegendItem color={FAIL_COLOR} label="Fail" value={failCount} />
									</div>
								</div>
							</div>
						</div>

						{/* Median Runtime */}
						<div className="border border-border rounded-md bg-card/30 p-3">
							<h4 className="text-[11px] text-muted-foreground uppercase mb-2 text-center font-semibold tracking-wider">
								Median Runtime (ms)
							</h4>
							<div className="flex h-[150px] flex-col justify-center gap-1.5">
								{runtimeData.map((row) => (
									<div
										key={row.command}
										className="grid grid-cols-[minmax(0,1.2fr)_minmax(60px,1.8fr)_40px] items-center gap-2 text-xs py-0.5 px-1 hover:bg-muted/10 rounded-sm transition-colors"
										title={`${row.command}: ${row.runtime}ms median`}
									>
										<span className="truncate font-mono text-muted-foreground" title={row.command}>
											{row.displayCommand}
										</span>
										<div className="h-1.5 rounded-sm bg-muted/40 overflow-hidden">
											<div
												className="h-full rounded-sm bg-primary transition-all duration-300"
												style={{
													width: `${Math.min(
														RUNTIME_BAR_MAX_WIDTH_PERCENT,
														Math.max(
															0,
															(row.runtime / maxRuntime) *
																RUNTIME_BAR_MAX_WIDTH_PERCENT,
														),
													)}%`,
												}}
											/>
										</div>
										<span className="text-right font-mono text-foreground">
											{row.runtime}
										</span>
									</div>
								))}
								{runtimeData.length === 0 && (
									<div className="px-4 py-8 text-center text-xs text-muted-foreground">
										No async jobs ran in this window
									</div>
								)}
							</div>
						</div>
					</div>

					{/* Noisy Commands */}
					<div className="border border-border rounded-md bg-card/30 p-3">
						<h4 className="text-[11px] text-muted-foreground uppercase tracking-wider mb-2 font-semibold">
							Noisy Commands (Highest Failure Rate)
						</h4>
						<div className="space-y-1">
							{noisy.map((c) => (
								<div key={c.command}>
									<button
										type="button"
										onClick={() =>
											setExpandedCmd(expandedCmd === c.command ? null : c.command)
										}
										className="w-full flex items-center justify-between px-2 py-1.5 rounded-sm hover:bg-muted/20 transition-colors text-xs"
									>
										<span className="font-mono break-all text-left mr-2">{c.command}</span>
										<div className="flex items-center gap-3 shrink-0">
											<span className="text-signal-deny font-medium">
												{(failureRate(c) * 100).toFixed(0)}% fail
											</span>
											<span className="text-muted-foreground">{c.total} runs</span>
										</div>
									</button>
									{expandedCmd === c.command && c.failures.length > 0 && (
										<pre className="mx-2 mt-1 mb-2 p-2 rounded-sm bg-background text-[11px] text-signal-deny/85 overflow-x-auto whitespace-pre-wrap break-all border border-border">
											{c.failures.join("\n---\n")}
										</pre>
									)}
								</div>
							))}
							{noisy.length === 0 && (
								<div className="px-2 py-3 text-center text-xs text-muted-foreground">
									No async command failures detected
								</div>
							)}
						</div>
					</div>
				</>
			)}
		</div>
	);
}

function LegendItem({
	color,
	label,
	value,
}: {
	color: string;
	label: string;
	value: number;
}) {
	return (
		<div className="flex items-center gap-2 text-xs">
			<span
				className="h-2.5 w-2.5 rounded-full"
				style={{ backgroundColor: color }}
			/>
			<span className="min-w-8">{label}</span>
			<span className="font-mono text-foreground font-semibold">{value}</span>
		</div>
	);
}

