"""Bounded, factual evidence collection for the run-wide progress narrator.

The narrator never sees raw token streams, whole graph-state payloads, or its
own prior output. It sees a small, newest-first-bounded set of normalized facts
derived from typed AG-UI events plus the optional navigation journey, so its
running explanation stays grounded in observed outcomes.
"""

from __future__ import annotations

from collections import deque
from dataclasses import dataclass
from typing import Final

from cloud.services.agent_runner.narrative.facts import (
    CONTROL_ID_KEY,
    KIND_KEY,
    TERMINAL_KEY,
    journey_candidate,
    normalize_event,
    normalize_journey,
)
from src.agui import BaseEvent
from src.autopilot.contracts.navigation import (
    UnsupportedNavigationJourneySchemaError,
    hydrate_navigation_journey,
)
from src.logging import get_logger
from src.types.typed import JsonObject

logger = get_logger(__name__)

_PREPARED_STATUS: Final[str] = "prepared"
_TOOL_KINDS: Final[frozenset[str]] = frozenset({"tool", "verify"})
_NAVIGATION_FAILURES: Final[tuple[type[Exception], ...]] = (
    UnsupportedNavigationJourneySchemaError,
    ValueError,
)


@dataclass(frozen=True)
class NarrativeSnapshot:
    """One immutable, factual view of recent run activity."""

    revision: int
    events: tuple[JsonObject, ...]
    navigation: JsonObject | None
    selected_next: tuple[JsonObject, ...]


def has_terminal_facts(snapshot: NarrativeSnapshot) -> bool:
    """Return whether the snapshot ends any observed outcome."""
    return any(record.get(TERMINAL_KEY) is True for record in snapshot.events)


class NarrativeEvidence:
    """Collects bounded facts and reports when they meaningfully change."""

    def __init__(self, *, max_events: int) -> None:
        self._records: deque[JsonObject] = deque(maxlen=max(max_events, 1))
        self._revision = 0
        self._navigation: JsonObject | None = None
        self._navigation_epoch: int | None = None
        self._pending_retries: dict[str, JsonObject] = {}

    def observe_event(self, event: BaseEvent) -> bool:
        """Record one event; return True when it adds a meaningful new fact."""
        record = normalize_event(event)
        if record is None:
            return False
        logger.debug(
            "run_narrative.observe_event",
            event_type=event.type,
            kind=record.get(KIND_KEY),
            revision=self._revision,
        )
        retry_changed = self._track_retry(record)
        if self._records and self._records[-1] == record:
            return retry_changed
        self._records.append(record)
        self._revision += 1
        return True

    def observe_state(self, snapshot: dict[str, object]) -> bool:
        """Record one root graph-state snapshot; return True on navigation change."""
        candidate = journey_candidate(snapshot)
        if candidate is None:
            return self._apply_navigation(None, None)
        try:
            journey = hydrate_navigation_journey(candidate)
        except _NAVIGATION_FAILURES as err:
            logger.warning(
                "run_narrative.invalid_navigation",
                error_type=type(err).__name__,
            )
            return self._apply_navigation(None, None)
        return self._apply_navigation(normalize_journey(journey), journey.page_epoch)

    def snapshot(self) -> NarrativeSnapshot:
        """Return an immutable snapshot of the currently retained facts."""
        return NarrativeSnapshot(
            revision=self._revision,
            events=tuple(self._records),
            navigation=(
                dict(self._navigation) if self._navigation is not None else None
            ),
            selected_next=self._selected_next(),
        )

    def _track_retry(self, record: JsonObject) -> bool:
        """Maintain retry selection from one fact; True when selection changed."""
        control_id = record.get(CONTROL_ID_KEY)
        if not isinstance(control_id, str):
            return False
        if record.get(KIND_KEY) == "retry":
            self._pending_retries[control_id] = record
            return True
        if record.get(KIND_KEY) in _TOOL_KINDS and control_id in self._pending_retries:
            del self._pending_retries[control_id]
            return True
        return False

    def _apply_navigation(self, navigation: JsonObject | None, epoch: int | None) -> bool:
        """Adopt a normalized navigation context; True when it changed."""
        if navigation == self._navigation and epoch == self._navigation_epoch:
            return False
        previous_epoch = self._navigation_epoch
        self._navigation = navigation
        self._navigation_epoch = epoch
        if previous_epoch != epoch:
            self._pending_retries.clear()
        self._revision += 1
        return True

    def _selected_next(self) -> tuple[JsonObject, ...]:
        """Return only selected future work: a prepared action and retries."""
        selected: list[JsonObject] = []
        pending = (
            self._navigation.get("pending_action")
            if self._navigation is not None
            else None
        )
        if isinstance(pending, dict) and pending.get("status") == _PREPARED_STATUS:
            selected.append({"kind": "navigation_action", **pending})
        selected.extend(self._pending_retries.values())
        return tuple(selected)


__all__ = [
    "NarrativeEvidence",
    "NarrativeSnapshot",
    "has_terminal_facts",
]

