from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass
from typing import cast

import src.key_catalog
from cloud.services.agent_runner_support.judge.types import ProfileExtractionResult
from src.agui import BaseEvent, PlannerStatusUpdate, PlannerToAGUIAdapter
from src.error_handling import build_error_outcome
from src.key_catalog import (
    OP_CHOOSE_OPTION,
    OP_SELECT_COMBOBOX,
    OP_SELECT_OPTION,
    OP_SET_BOOLEAN,
    OP_SET_TEXT,
    OP_UPLOAD_ATTACHMENT,
    PK_ATTACHMENT_SLOT,
    PK_CONTROL_ID,
    PK_CURRENT_VALUE,
    PK_EXPECTED_OPTION,
    PK_FIELD,
    PK_OPERATION,
    PK_PROFILE_DATA,
    PK_TEXT,
    PK_VALUE,
    SK_STATUS_UPDATES,
)
from src.logging import get_logger
from src.types.payload import resolve_profile_data
from src.types.typed import JsonObject, as_json_object, as_json_value
from src.types.types import JsonValue

logger = get_logger(__name__)


def coerce_json_object_list(value: object) -> list[JsonObject]:
    if not isinstance(value, list):
        return []
    items: list[JsonObject] = []
    raw_items = cast(list[object], value)
    for item in raw_items:
        if isinstance(item, dict):
            items.append(cast(JsonObject, item))
    return items


def document_asset_selection(result: dict[str, object]) -> JsonObject | None:
    """Extract top-level or latest valid tailoring status selection metadata."""
    selection = as_json_object(result.get("document_asset_selection")) or None

    if selection is None:
        for status_update in reversed(
            coerce_json_object_list(result.get(SK_STATUS_UPDATES))
        ):
            details = as_json_object(status_update.get("details"))
            selection = as_json_object(details.get("document_asset_selection")) or None
            if selection is not None:
                break
    return selection


def as_optional_string(value: object) -> str | None:
    if isinstance(value, str):
        return value
    return None


def as_optional_float(value: object) -> float | None:
    if isinstance(value, bool):
        return None
    if isinstance(value, int | float):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value)
        except ValueError as exc:
            logger.warning(
                "Unable to parse optional float payload value",
                value_preview=value[:80],
                value_length=len(value),
                exception_type=type(exc).__name__,
                exc_info=exc,
            )
            return None
    return None


@dataclass(frozen=True)
class ParseErrorContext:
    """Grouped context for parse-error diagnostics."""

    source: str
    field_name: str
    context: JsonObject
    message: str


def as_optional_float_result(
    value: object,
    error_ctx: ParseErrorContext,
) -> tuple[float | None, JsonObject | None]:
    parsed = as_optional_float(value)
    if parsed is not None or value is None:
        return parsed, None
    enriched_context = dict(error_ctx.context)
    enriched_context[PK_FIELD] = error_ctx.field_name
    enriched_context["value_type"] = type(value).__name__
    if isinstance(value, str) and value.strip():
        enriched_context["value_preview"] = value[:80]
    return (
        None,
        build_error_outcome(
            ValueError(error_ctx.message),
            context=enriched_context,
            severity=src.key_catalog.SV_WARNING,
            recoverable=True,
            source=error_ctx.source,
            message=error_ctx.message,
        ).to_payload(),
    )


def action_control_id(action: JsonObject) -> str:
    return as_optional_string(action.get(PK_CONTROL_ID)) or ""


def build_planner_summary(action: JsonObject) -> str:
    """Deprecated: returns empty so real LLM reasoning isn't masked by templates.

    Callers must source planner reasoning from PlannerAction.reasoning or judge_reason.
    """
    del action
    return ""


def field_control_id(field_payload: JsonObject) -> str:
    return as_optional_string(field_payload.get(PK_CONTROL_ID)) or ""


@dataclass(frozen=True)
class PayloadFieldView:
    """Typed owner for payload control projections used by helper flows."""

    fields: tuple[JsonObject, ...]

    @classmethod
    def from_payload(cls, payload: JsonObject) -> PayloadFieldView:
        raw_fields = payload.get(src.key_catalog.PK_CONTROLS)
        if not isinstance(raw_fields, list):
            return cls(fields=())
        return cls(
            fields=tuple(
                cast(JsonObject, raw)
                for raw in cast(list[object], raw_fields)
                if isinstance(raw, dict)
            )
        )

    def by_control_id(self) -> dict[str, JsonObject]:
        return {cid: fld for fld in self.fields if (cid := field_control_id(fld))}

    def current_values(self) -> dict[str, str | None]:
        return {
            cid: (
                current_value
                if isinstance(current_value := fld.get(PK_CURRENT_VALUE), str)
                else None
            )
            for fld in self.fields
            if (cid := field_control_id(fld))
        }


def write_action_target_value(action: JsonObject, value: JsonValue) -> None:
    """Set the operation-keyed value slot ("text" vs "expected_option") in place."""
    coerced = as_json_value(value)
    if action.get(PK_OPERATION) == OP_SET_TEXT:
        action[PK_TEXT] = coerced
    else:
        action[PK_EXPECTED_OPTION] = coerced


def action_display_value(action: JsonObject) -> JsonValue | None:
    operation = as_optional_string(action.get(PK_OPERATION)) or ""
    if operation == OP_SET_TEXT:
        return as_optional_string(action.get(PK_TEXT))
    if (
        operation in {OP_SELECT_OPTION, OP_SELECT_COMBOBOX, OP_CHOOSE_OPTION}
        and PK_EXPECTED_OPTION in action
    ):
        return action.get(PK_EXPECTED_OPTION)
    if operation == OP_SET_BOOLEAN:
        raw_value = action.get(PK_VALUE)
        if isinstance(raw_value, bool):
            return raw_value
    if operation == OP_UPLOAD_ATTACHMENT:
        return as_optional_string(action.get(PK_ATTACHMENT_SLOT))
    if PK_VALUE in action:
        return action.get(PK_VALUE)
    return None


def emit_status_events(
    adapter: PlannerToAGUIAdapter,
    update: PlannerStatusUpdate | Mapping[str, object],
) -> list[BaseEvent]:
    typed_update = (
        update
        if isinstance(update, PlannerStatusUpdate)
        else PlannerStatusUpdate.from_mapping(update)
    )
    logger.info(
        "agent_runner.emit_status_events",
        stage=typed_update.stage,
        status_level=typed_update.level,
    )
    return adapter.adapt_status_update(typed_update)


def extract_profile_result(payload: JsonObject) -> ProfileExtractionResult:
    profile_data = resolve_profile_data(payload)
    candidate = payload.get(PK_PROFILE_DATA)
    if isinstance(candidate, dict):
        return ProfileExtractionResult(profile_data=profile_data)
    if candidate is None:
        return ProfileExtractionResult(profile_data={})
    error = build_error_outcome(
        ValueError(
            "Profile payload was malformed; cloud helpers fell back to an empty profile."
        ),
        context={"profile_data_type": type(candidate).__name__},
        severity=src.key_catalog.SV_WARNING,
        recoverable=True,
        source="agent_runner.profile_extract",
        message="Profile payload was malformed; cloud helpers fell back to an empty profile.",
    ).to_payload()
    return ProfileExtractionResult(profile_data={}, error=error)


def extract_profile(payload: JsonObject) -> JsonObject:
    return extract_profile_result(payload).profile_data

