"""Probe 2: interrupt seam + cli lazy-export shapes."""

from __future__ import annotations

from collections.abc import Callable, Mapping
from types import ModuleType

type PackageCallable = Callable[..., object]
type InterruptCallable = Callable[[dict[str, object]], object]


def package_callable(
    package: ModuleType,
    export_name: str,
    error_message: str,
) -> PackageCallable:
    """Resolve an export from an already-imported package module."""
    candidate = vars(package).get(export_name)
    if not callable(candidate):
        raise TypeError(error_message)
    return candidate


def call_package_interrupt(
    package: ModuleType,
    payload: Mapping[str, object],
) -> object:
    """Invoke a package's exported interrupt with a mutable copy of the payload."""
    package_interrupt: InterruptCallable = package_callable(
        package,
        "interrupt",
        "package interrupt must be callable",
    )
    return package_interrupt(dict(payload))


def caller_absolute() -> ModuleType:
    """Deferred absolute import of the owning subpackage."""
    from src.autopilot.graph.nodes.orchestration import human_review as package

    return package


def caller_relative_attr() -> object:
    """Deferred relative import of a package-exported callable."""
    from . import interrupt

    return interrupt


def cli_module_loader() -> ModuleType:
    """Literal-argument import inside a loader."""
    from importlib import import_module

    return import_module("src.cli.types")
